(function(){"use strict";if(document.readyState!=="loading"){throw new Error("Blogger embed must load synchronously during HTML parsing");}document.write("<div>\n\n<!--=========================================================\n     TRANG TRA C\u1ee8U H\u1eccC VI\u00caN\n     PROFILE MARKET v4.9.6\n     + ADMIN QUICK ACTIONS\n     + LEARNING INSIGHT v1.6\n     + MINH H\u1ed2NG SESSION BRIDGE\n\n     UPDATE v1.6\n     ---------------------------------------------------------\n     - B\u1ecf ho\u00e0n to\u00e0n kh\u1ed1i Minh H\u1ed3ng ri\u00eang kh\u1ecfi trang\n     - B\u1ecf \"V\u1eadt ph\u1ea9m n\u00ean \u01b0u ti\u00ean\" kh\u1ecfi giao di\u1ec7n trang\n     - V\u1eabn GI\u1eee to\u00e0n b\u1ed9 engine t\u00ednh l\u1eddi khuy\u00ean\n     - V\u1eabn GI\u1eee engine ch\u1ecdn v\u1eadt ph\u1ea9m C\u1ef1c ph\u1ea9m\n     - (v1.7.1) \u0110\u00e3 b\u1ecf ph\u1ea7n g\u1eedi l\u1eddi khuy\u00ean sang Minh H\u1ed3ng\n     - Ng\u0169 gi\u00e1c ch\u1ec9 s\u1ed1 + h\u1ed3 s\u01a1 ph\u00e2n t\u00edch hi\u1ec3n th\u1ecb ngay tr\u00ean trang\n     - T\u1ef1 \u0111\u1ecdc m\u00e3 t\u1eeb OCDStudentSession\n     - T\u1ef1 \u0111i\u1ec1n m\u00e3 v\u00e0o \u00f4 tra c\u1ee9u\n     - C\u00f3 th\u1ec3 t\u1ef1 k\u00edch ho\u1ea1t tra c\u1ee9u\n     - Ch\u1ec9 CONFIRM Session sau khi h\u1ed3 s\u01a1 t\u1ea3i th\u00e0nh c\u00f4ng\n     - ADMIN kh\u00f4ng ghi v\u00e0o Student Session\n\n     GI\u1eee:\n     - Tra c\u1ee9u\n     - H\u1ed3 s\u01a1\n     - Linh th\u1ea1ch\n     - V\u1eadt ph\u1ea9m\n     - Ch\u1ee3 phi\u00ean\n     - Danh s\u00e1ch b\u00e0i\n     - Rank\n     - Bi\u1ec3u \u0111\u1ed3\n     - M\u1ed1c m\u1ee5c ti\u00eau\n     - Cache\n     - Lazy load\n     - Entity fix\n=========================================================-->\n\n\n<!--=========================================================\n     PROFILE MARKET G\u1ed0C\n=========================================================-->\n\n<link href=\"https://cdn.jsdelivr.net/gh/vnthudao-source/ocd4-assets@v18.5.1/profile-market.css\" rel=\"stylesheet\"></link>\n\n<script src=\"https://cdn.jsdelivr.net/gh/vnthudao-source/ocd4-assets@6a50f511325148ccf42d60b81ad75ccbf86cd1ce/profile-market.min.js\"></script>\n\n<!-- Ng\u0169 gi\u00e1c ch\u1ec9 s\u1ed1 v1.1.0 -->\n<script src=\"https://cdn.jsdelivr.net/gh/vnthudao-source/ocd4-assets@6cfcb0e36c5947356e3180c193625e8b7d712237/profile-pentagon.min.js\"></script>\n\n\n<style>\n\n/* =========================================================\n   ADMIN\n========================================================= */\n\n.student-profile-badge.admin-quick-action{\n    padding:0 !important;\n    overflow:hidden;\n    background:transparent !important;\n    border:0 !important;\n}\n\n.student-profile-badge.admin-quick-action .admin-original-icon{\n    display:none !important;\n}\n\n.student-profile-badge.admin-quick-action .admin-quick-action-text{\n    display:block;\n    width:100%;\n}\n\n.admin-profile-link{\n    display:inline-flex;\n    align-items:center;\n    justify-content:center;\n    gap:6px;\n\n    width:100%;\n    min-height:36px;\n\n    padding:8px 13px;\n\n    box-sizing:border-box;\n\n    border-radius:999px;\n\n    color:#fff !important;\n    text-decoration:none !important;\n\n    font-size:11px;\n    line-height:1.25;\n    font-weight:900;\n\n    white-space:nowrap;\n\n    cursor:pointer;\n\n    box-shadow:\n        0 5px 14px rgba(15,23,42,.14);\n\n    transition:\n        transform .16s ease,\n        box-shadow .16s ease,\n        filter .16s ease;\n}\n\n.admin-profile-link:hover{\n    transform:translateY(-1px);\n\n    box-shadow:\n        0 7px 18px rgba(15,23,42,.18);\n\n    filter:brightness(1.04);\n}\n\n.admin-grade-link{\n    background:\n        linear-gradient(\n            135deg,\n            #2563eb,\n            #4f46e5\n        );\n}\n\n.admin-gift-link{\n    background:\n        linear-gradient(\n            135deg,\n            #7c3aed,\n            #c026d3\n        );\n}\n\n.admin-graduation-link{\n    background:\n        linear-gradient(\n            135deg,\n            #9a3412,\n            #b45309\n        );\n}\n\n\n/* =========================================================\n   INSIGHT ROOT\n========================================================= */\n\n#studentInsightSection{\n    display:none;\n\n    max-width:1100px;\n\n    margin:24px auto 0;\n\n    font-family:\n        Arial,\n        Helvetica,\n        sans-serif;\n\n    color:#332b26;\n}\n\n#studentInsightSection.visible{\n    display:block;\n}\n\n.insight-shell{\n    overflow:hidden;\n\n    background:#fff;\n\n    border:1px solid #eadfce;\n    border-radius:22px;\n\n    box-shadow:\n        0 10px 30px rgba(72,48,30,.10);\n}\n\n\n/* =========================================================\n   HEADER\n========================================================= */\n\n.insight-header{\n    padding:26px 25px 22px;\n\n    background:\n        radial-gradient(\n            circle at 90% 0%,\n            rgba(245,158,11,.16),\n            transparent 32%\n        ),\n        linear-gradient(\n            135deg,\n            #fffaf1,\n            #fff\n        );\n\n    border-bottom:1px solid #f0e6d8;\n}\n\n.insight-kicker{\n    margin-bottom:5px;\n\n    color:#a16207;\n\n    font-size:10px;\n    font-weight:900;\n\n    letter-spacing:.12em;\n}\n\n.insight-title{\n    margin:0;\n\n    color:#633718;\n\n    font-size:24px;\n    line-height:1.25;\n    font-weight:900;\n}\n\n.insight-desc{\n    max-width:780px;\n\n    margin:7px 0 0;\n\n    color:#746a62;\n\n    font-size:12px;\n    line-height:1.65;\n}\n\n\n/* =========================================================\n   BODY\n========================================================= */\n\n.insight-body{\n    padding:22px;\n}\n\n.insight-loading{\n    display:none;\n\n    padding:18px;\n\n    border-radius:14px;\n\n    background:#eff6ff;\n    color:#1d4ed8;\n\n    text-align:center;\n\n    font-size:12px;\n    font-weight:800;\n}\n\n.insight-loading.visible{\n    display:block;\n}\n\n.insight-content{\n    display:none;\n}\n\n.insight-content.visible{\n    display:block;\n}\n\n\n/* =========================================================\n   SUMMARY\n========================================================= */\n\n.insight-summary-grid{\n    display:grid;\n\n    grid-template-columns:\n        repeat(\n            4,\n            minmax(0,1fr)\n        );\n\n    gap:10px;\n}\n\n.insight-stat{\n    min-width:0;\n\n    padding:15px 12px;\n\n    border:1px solid #eee5d9;\n\n    border-radius:15px;\n\n    background:#fffdf9;\n\n    text-align:center;\n}\n\n.insight-stat-value{\n    display:block;\n\n    overflow:hidden;\n\n    color:#713f12;\n\n    font-size:22px;\n    line-height:1.1;\n    font-weight:900;\n\n    white-space:nowrap;\n    text-overflow:ellipsis;\n}\n\n.insight-stat-label{\n    display:block;\n\n    margin-top:6px;\n\n    color:#78716c;\n\n    font-size:9px;\n    line-height:1.35;\n    font-weight:900;\n\n    text-transform:uppercase;\n}\n\n\n/* =========================================================\n   RANK\n========================================================= */\n\n.insight-rank-box{\n    display:grid;\n\n    grid-template-columns:\n        minmax(0,1fr)\n        auto;\n\n    gap:13px;\n\n    align-items:center;\n\n    margin-top:12px;\n\n    padding:15px 16px;\n\n    border:1px solid #ead9bc;\n\n    border-radius:15px;\n\n    background:\n        linear-gradient(\n            135deg,\n            #fff9e9,\n            #fff\n        );\n}\n\n.insight-rank-label{\n    color:#9a5b13;\n\n    font-size:9px;\n    font-weight:900;\n\n    text-transform:uppercase;\n}\n\n.insight-rank-name{\n    margin-top:4px;\n\n    color:#5c361f;\n\n    font-size:17px;\n    font-weight:900;\n}\n\n.insight-rank-next{\n    margin-top:5px;\n\n    color:#746a62;\n\n    font-size:10.5px;\n    line-height:1.55;\n}\n\n.insight-rank-icon{\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    width:50px;\n    height:50px;\n\n    border-radius:50%;\n\n    background:#fef3c7;\n\n    font-size:25px;\n}\n\n\n/* =========================================================\n   SECTION\n========================================================= */\n\n.insight-section{\n    margin-top:17px;\n}\n\n.insight-section-head{\n    margin-bottom:11px;\n}\n\n.insight-section-title{\n    display:flex;\n\n    align-items:center;\n\n    gap:7px;\n\n    color:#4c2f20;\n\n    font-size:18px;\n    font-weight:900;\n}\n\n.insight-section-desc{\n    margin-top:3px;\n\n    color:#8a817a;\n\n    font-size:10px;\n    line-height:1.5;\n}\n\n\n/* =========================================================\n   CARD\n========================================================= */\n\n.insight-card{\n    min-width:0;\n\n    padding:18px;\n\n    border:1px solid #ece4d9;\n\n    border-radius:17px;\n\n    background:#fff;\n}\n\n.insight-card-title{\n    display:flex;\n\n    align-items:center;\n\n    gap:7px;\n\n    margin-bottom:5px;\n\n    color:#5b3925;\n\n    font-size:16px;\n    line-height:1.35;\n    font-weight:900;\n}\n\n.insight-card-subtitle{\n    margin-bottom:13px;\n\n    color:#8a817a;\n\n    font-size:10px;\n    line-height:1.5;\n}\n\n\n/* =========================================================\n   CHART\n========================================================= */\n\n.insight-trend-row{\n    display:grid;\n\n    grid-template-columns:\n        minmax(0,1.35fr)\n        minmax(0,.65fr);\n\n    gap:14px;\n\n    margin-top:14px;\n}\n\n.insight-chart-wrap{\n    position:relative;\n\n    width:100%;\n    min-height:250px;\n\n    overflow:hidden;\n\n    border:1px solid #f0e7db;\n\n    border-radius:13px;\n\n    background:\n        linear-gradient(\n            to bottom,\n            rgba(250,245,237,.55),\n            rgba(255,255,255,.95)\n        );\n}\n\n#studentProgressChart{\n    display:block;\n\n    width:100%;\n    min-height:250px;\n}\n\n.insight-chart-empty{\n    display:none;\n\n    min-height:250px;\n\n    align-items:center;\n    justify-content:center;\n\n    padding:20px;\n\n    color:#948b83;\n\n    text-align:center;\n\n    font-size:11px;\n    line-height:1.5;\n}\n\n.insight-chart-empty.visible{\n    display:flex;\n}\n\n.insight-chart-wrap.is-empty #studentProgressChart{\n    display:none;\n}\n\n\n/* =========================================================\n   TREND\n========================================================= */\n\n.insight-trend-box{\n    height:100%;\n    min-height:210px;\n\n    display:flex;\n    flex-direction:column;\n\n    justify-content:center;\n    align-items:center;\n\n    text-align:center;\n}\n\n.insight-trend-icon{\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    width:54px;\n    height:54px;\n\n    margin-bottom:9px;\n\n    border-radius:50%;\n\n    background:#f8fafc;\n\n    font-size:28px;\n}\n\n.insight-trend-name{\n    font-size:19px;\n    font-weight:900;\n}\n\n.insight-trend-detail{\n    margin-top:8px;\n\n    color:#78716c;\n\n    font-size:11px;\n    line-height:1.55;\n}\n\n.insight-trend-box.up .insight-trend-name{\n    color:#15803d;\n}\n\n.insight-trend-box.down .insight-trend-name{\n    color:#b91c1c;\n}\n\n.insight-trend-box.stable .insight-trend-name{\n    color:#a16207;\n}\n\n.insight-trend-box.insufficient .insight-trend-name{\n    color:#64748b;\n}\n\n\n/* =========================================================\n   GOALS\n========================================================= */\n\n.insight-goal-grid{\n    display:grid;\n\n    grid-template-columns:\n        repeat(\n            3,\n            minmax(0,1fr)\n        );\n\n    gap:10px;\n}\n\n.insight-goal{\n    position:relative;\n\n    overflow:hidden;\n\n    padding:15px;\n\n    border:1px solid #eadfce;\n\n    border-radius:15px;\n\n    background:\n        linear-gradient(\n            145deg,\n            #fffdf9,\n            #fff\n        );\n}\n\n.insight-goal-badge{\n    display:inline-block;\n\n    margin-bottom:8px;\n\n    padding:4px 8px;\n\n    border-radius:999px;\n\n    background:#fef3c7;\n\n    color:#92400e;\n\n    font-size:8px;\n    font-weight:900;\n\n    text-transform:uppercase;\n}\n\n.insight-goal-name{\n    color:#4b3325;\n\n    font-size:13px;\n    line-height:1.4;\n    font-weight:900;\n}\n\n.insight-goal-detail{\n    margin-top:6px;\n\n    min-height:38px;\n\n    color:#786f68;\n\n    font-size:10px;\n    line-height:1.55;\n}\n\n.insight-progress{\n    height:7px;\n\n    margin-top:11px;\n\n    overflow:hidden;\n\n    border-radius:999px;\n\n    background:#eee8e0;\n}\n\n.insight-progress-bar{\n    height:100%;\n\n    width:0;\n\n    border-radius:inherit;\n\n    background:\n        linear-gradient(\n            90deg,\n            #d97706,\n            #f59e0b\n        );\n}\n\n.insight-progress-caption{\n    margin-top:6px;\n\n    color:#8a817a;\n\n    font-size:9px;\n    font-weight:700;\n}\n\n\n/* =========================================================\n   NOTE\n========================================================= */\n\n.insight-note{\n    margin-top:14px;\n\n    padding:10px 12px;\n\n    border-radius:11px;\n\n    background:#f8fafc;\n\n    color:#64748b;\n\n    font-size:9px;\n    line-height:1.55;\n}\n\n\n/* =========================================================\n   MOBILE\n========================================================= */\n\n@media(max-width:800px){\n\n    .insight-summary-grid{\n        grid-template-columns:\n            repeat(\n                2,\n                minmax(0,1fr)\n            );\n    }\n\n    .insight-trend-row{\n        grid-template-columns:1fr;\n    }\n\n    .insight-goal-grid{\n        grid-template-columns:1fr;\n    }\n\n}\n\n\n@media(max-width:600px){\n\n    .admin-profile-link{\n        min-height:34px;\n\n        padding:7px 9px;\n\n        font-size:9.5px;\n\n        white-space:normal;\n\n        text-align:center;\n    }\n\n    #studentInsightSection{\n        margin:\n            18px\n            8px\n            0;\n    }\n\n    .insight-header{\n        padding:\n            20px\n            16px\n            18px;\n    }\n\n    .insight-title{\n        font-size:21px;\n    }\n\n    .insight-body{\n        padding:14px;\n    }\n\n    .insight-stat{\n        padding:13px 8px;\n    }\n\n    .insight-stat-value{\n        font-size:20px;\n    }\n\n    .insight-card{\n        padding:13px;\n    }\n\n    .insight-chart-wrap,\n    #studentProgressChart,\n    .insight-chart-empty{\n        min-height:220px;\n    }\n\n}\n\n</style>\n\n\n<!--=========================================================\n     APP\n=========================================================-->\n\n<div id=\"rewardExchangeApp\">\n\n    <div class=\"rx-title\">\n        H\u1ed2 S\u01a0 H\u1eccC VI\u00caN\n    </div>\n\n    <div class=\"rx-desc\">\n        Tra c\u1ee9u h\u1ed3 s\u01a1, linh th\u1ea1ch, v\u1eadt ph\u1ea9m v\u00e0 Ch\u1ee3 phi\u00ean.\n    </div>\n\n\n    <!--=====================================================\n         SEARCH\n    ======================================================-->\n\n    <section class=\"rx-search\">\n\n        <div class=\"rx-section-title\">\n            Tra c\u1ee9u h\u1ed3 s\u01a1\n        </div>\n\n        <div class=\"rx-day\">\n            Nh\u1eadp \u0111\u00fang M\u00e3 h\u1ecdc vi\u00ean \u0111\u1ec3 m\u1edf h\u1ed3 s\u01a1.\n        </div>\n\n\n        <div class=\"rx-search-row\">\n\n            <input autocomplete=\"off\" class=\"rx-input\" id=\"rxStudentCode\" placeholder=\"Nh\u1eadp M\u00e3 h\u1ecdc vi\u00ean...\" spellcheck=\"false\" type=\"text\" />\n\n\n            <button class=\"rx-search-btn\" id=\"rxSearchButton\" type=\"button\">\n                TRA C\u1ee8U\n            </button>\n\n        </div>\n\n\n        <div class=\"rx-message\" id=\"rxMessage\"></div>\n\n\n        <!--PROFILE-->\n\n        <div class=\"student-profile-module\" id=\"studentProfileModule\">\n\n            <div class=\"student-profile-overlay\"></div>\n\n\n            <div class=\"student-profile-inner\">\n\n                <div class=\"student-profile-main\">\n\n                    <div class=\"student-profile-avatar\" id=\"studentProfileAvatar\"></div>\n\n\n                    <div class=\"student-profile-content\">\n\n                        <div class=\"student-profile-label\">\n                            H\u1ed2 S\u01a0 H\u1eccC VI\u00caN\n                        </div>\n\n\n                        <div class=\"student-profile-name-wrap\" id=\"studentProfileNameWrap\">\n\n                            <div class=\"student-profile-name\" id=\"studentProfileName\"></div>\n\n                        </div>\n\n\n                        <div class=\"student-profile-badges\">\n\n                            <div class=\"student-profile-badge\">\n\n                                <span class=\"admin-original-icon\" id=\"profileStreakIcon\"></span>\n\n                                <span class=\"admin-quick-action-text\" id=\"profileStreakText\"></span>\n\n                            </div>\n\n\n                            <div class=\"student-profile-badge\">\n\n                                <span class=\"admin-original-icon\" id=\"profileHighIcon\"></span>\n\n                                <span class=\"admin-quick-action-text\" id=\"profileHighText\"></span>\n\n                            </div>\n\n\n                            <div class=\"student-profile-badge\">\n\n                                <span class=\"admin-original-icon\" id=\"profileTitleIcon\"></span>\n\n                                <span class=\"admin-quick-action-text\" id=\"profileTitleText\"></span>\n\n                            </div>\n\n                        </div>\n\n                    </div>\n\n                </div>\n\n\n                <div class=\"student-profile-actions\">\n\n                    <button class=\"student-profile-action\" id=\"profileLearningButton\" type=\"button\">\n\n                        <span id=\"profileLearningIcon\"></span>\n\n                        <span>\n                            Th\u00f4ng tin h\u1ecdc t\u1eadp\n                        </span>\n\n                    </button>\n\n\n                    <button class=\"student-profile-action\" id=\"profileGemButton\" type=\"button\">\n\n                        <span id=\"profileGemIcon\"></span>\n\n                        <span>\n                            Linh th\u1ea1ch\n                        </span>\n\n                        <span class=\"student-profile-action-number\" id=\"profileGemTotal\">\n                            0\n                        </span>\n\n                    </button>\n\n\n                    <button class=\"student-profile-action\" id=\"profileItemButton\" type=\"button\">\n\n                        <span id=\"profileItemIcon\"></span>\n\n                        <span>\n                            V\u1eadt ph\u1ea9m\n                        </span>\n\n                        <span class=\"student-profile-action-number\" id=\"profileItemTotal\">\n                            0\n                        </span>\n\n                    </button>\n\n                </div>\n\n            </div>\n\n        </div>\n\n\n        <!--LEARNING-->\n\n        <div class=\"rx-expand-panel\" id=\"profileLearningPanel\">\n\n            <div class=\"rx-panel-title\">\n                Th\u00f4ng tin h\u1ecdc t\u1eadp\n            </div>\n\n\n            <div class=\"learning-info-grid\">\n\n                <div class=\"learning-info-item\">\n\n                    <div class=\"learning-info-label\">\n                        T\u1ed5\n                    </div>\n\n                    <div class=\"learning-info-value\" id=\"learningGroup\">\n                        -\n                    </div>\n\n                </div>\n\n\n                <div class=\"learning-info-item\">\n\n                    <div class=\"learning-info-label\">\n                        Kh\u00f3a\n                    </div>\n\n                    <div class=\"learning-info-value\" id=\"learningCourse\">\n                        -\n                    </div>\n\n                </div>\n\n\n                <div class=\"learning-info-item\">\n\n                    <div class=\"learning-info-label\">\n                        \u0110i\u1ec3m trung b\u00ecnh\n                    </div>\n\n                    <div class=\"learning-info-value learning-average\" id=\"learningAverage\">\n                        -\n                    </div>\n\n                </div>\n\n\n                <div class=\"learning-info-item\">\n\n                    <div class=\"learning-info-label\">\n                        \u0110i\u1ec3m x\u1ebfp h\u1ea1ng\n                    </div>\n\n                    <div class=\"learning-info-value learning-ranking\" id=\"learningRanking\">\n                        -\n                    </div>\n\n                </div>\n\n            </div>\n\n\n            <div class=\"learning-status\" id=\"learningStatus\">\n\n                <div class=\"learning-status-title\" id=\"learningStatusTitle\"></div>\n\n                <div id=\"learningStatusDetail\"></div>\n\n            </div>\n\n\n            <div class=\"submission-section\" id=\"submissionSection\">\n\n                <button class=\"submission-toggle-button\" id=\"submissionToggleButton\" type=\"button\">\n\n                    <div class=\"submission-toggle-inner\">\n\n                        <div class=\"submission-toggle-left\">\n\n                            <span id=\"submissionBookIcon\"></span>\n\n                            <span>\n                                Danh s\u00e1ch b\u00e0i \u0111\u00e3 n\u1ed9p\n                            </span>\n\n                            <span class=\"submission-toggle-count\" id=\"submissionCount\"></span>\n\n                        </div>\n\n\n                        <span class=\"submission-toggle-arrow\" id=\"submissionSafeArrow\"></span>\n\n                    </div>\n\n                </button>\n\n\n                <div class=\"submission-content\" id=\"submissionContent\">\n\n                    <div class=\"submission-table-wrapper\">\n\n                        <table class=\"submission-table\">\n\n                            <thead>\n\n                                <tr>\n\n                                    <th>STT</th>\n\n                                    <th>\n                                        Th\u1eddi gian n\u1ed9p\n                                    </th>\n\n                                    <th>\n                                        B\u00e0i t\u1eadp\n                                    </th>\n\n                                    <th>\n                                        \u0110i\u1ec3m s\u1ed1\n                                    </th>\n\n                                    <th>\n                                        Nh\u1eadn x\u00e9t\n                                    </th>\n\n                                </tr>\n\n                            </thead>\n\n\n                            <tbody id=\"submissionTableBody\"></tbody>\n\n                        </table>\n\n                    </div>\n\n                </div>\n\n            </div>\n\n        </div>\n\n\n        <!--GEMS-->\n\n        <div class=\"rx-expand-panel\" id=\"profileGemPanel\">\n\n            <div class=\"rx-panel-title\">\n                Linh th\u1ea1ch hi\u1ec7n c\u00f3\n            </div>\n\n            <div class=\"profile-gem-grid\" id=\"profileGemGrid\"></div>\n\n        </div>\n\n\n        <!--ITEMS-->\n\n        <div class=\"rx-expand-panel\" id=\"profileItemPanel\">\n\n            <div class=\"rx-panel-title\">\n                V\u1eadt ph\u1ea9m \u0111ang s\u1edf h\u1eefu\n            </div>\n\n            <div class=\"profile-item-grid\" id=\"profileItemGrid\"></div>\n\n        </div>\n\n    </section>\n\n\n    <!--=====================================================\n         MARKET\n    ======================================================-->\n\n    <div class=\"market-toggle-wrap\">\n\n        <button class=\"market-toggle-button\" id=\"marketToggleButton\" type=\"button\">\n\n            <div class=\"market-toggle-content\">\n\n                <div class=\"market-toggle-left\">\n\n                    <div class=\"market-toggle-icon\" id=\"marketToggleIcon\"></div>\n\n\n                    <div>\n\n                        <div class=\"market-toggle-title\">\n                            Ch\u1ee3 phi\u00ean thu \u0111\u1ed5i linh th\u1ea1ch\n                        </div>\n\n                        <div class=\"market-toggle-subtitle\">\n                            Gi\u00e1 \u0111\u1ed5i \u0111\u01b0\u1ee3c l\u00e0m m\u1edbi theo ng\u00e0y.\n                            Giao d\u1ecbch \u0111\u01b0\u1ee3c x\u00e1c nh\u1eadn tr\u1ef1c ti\u1ebfp tr\u00ean trang.\n                        </div>\n\n                    </div>\n\n                </div>\n\n\n                <div class=\"market-toggle-arrow\" id=\"marketSafeArrow\"></div>\n\n            </div>\n\n        </button>\n\n\n        <div class=\"rx-market-panel\" id=\"marketPanel\">\n\n            <div class=\"rx-market-day\" id=\"marketDayLabel\">\n                M\u1edf Ch\u1ee3 phi\u00ean \u0111\u1ec3 t\u1ea3i d\u1eef li\u1ec7u h\u00f4m nay.\n            </div>\n\n\n            <div class=\"rx-message\" id=\"rxMarketMessage\"></div>\n\n\n            <div class=\"rx-grid\" id=\"rxNpcGrid\"></div>\n\n\n            <div class=\"market-info-area\">\n\n                <details class=\"market-info-details\">\n\n                    <summary>\n\n                        <span class=\"market-info-title\">\n\n                            <span id=\"marketIntroSafeIcon\"></span>\n\n                            <span>\n                                Gi\u1edbi thi\u1ec7u\n                            </span>\n\n                        </span>\n\n\n                        <span class=\"market-info-arrow safe-down-arrow\"></span>\n\n                    </summary>\n\n\n                    <div class=\"market-info-body\">\n\n                        <p>\n                            <strong>\n                                Ch\u1ee3 phi\u00ean thu \u0111\u1ed5i linh th\u1ea1ch\n                            </strong>\n                            l\u00e0 n\u01a1i c\u00e1c th\u01b0\u01a1ng nh\u00e2n gh\u00e9 qua m\u1ed7i ng\u00e0y.\n                        </p>\n\n                        <p>\n                            V\u1eadt ph\u1ea9m \u0111\u01b0\u1ee3c chia th\u00e0nh\n                            <strong>\n                                6 ph\u1ea9m c\u1ea5p\n                            </strong>\n                            t\u01b0\u01a1ng \u1ee9ng v\u1edbi h\u1ec7 th\u1ed1ng ph\u1ea7n th\u01b0\u1edfng.\n                        </p>\n\n                        <p>\n                            Vi\u1ec7c mua b\u00e1n v\u1eadt ph\u1ea9m trong h\u1ec7 th\u1ed1ng\n                            s\u1eed d\u1ee5ng H\u1ed3ng Ng\u1ecdc.\n                        </p>\n\n                        <p>\n                            <a href=\"https://www.thudao.com/2026/09/gioi-thieu-chuc-nang-cho-phien.html?m=1\" target=\"_blank\" rel=\"noopener\" style=\"color:#9a3f2c;font-weight:700;text-decoration:underline\">T\u00ecm hi\u1ec3u th\u00eam \u2192</a>\n                        </p>\n\n                    </div>\n\n                </details>\n\n\n                <details class=\"market-info-details\">\n\n                    <summary>\n\n                        <span class=\"market-info-title\">\n\n                            <span id=\"marketGuideSafeIcon\"></span>\n\n                            <span>\n                                H\u01b0\u1edbng d\u1eabn\n                            </span>\n\n                        </span>\n\n\n                        <span class=\"market-info-arrow safe-down-arrow\"></span>\n\n                    </summary>\n\n\n                    <div class=\"market-info-body\">\n\n                        <p>\n                            <strong>B\u01b0\u1edbc 1:</strong>\n                            Nh\u1eadp M\u00e3 h\u1ecdc vi\u00ean.\n                        </p>\n\n                        <p>\n                            <strong>B\u01b0\u1edbc 2:</strong>\n                            Ki\u1ec3m tra s\u1ed1 H\u1ed3ng Ng\u1ecdc.\n                        </p>\n\n                        <p>\n                            <strong>B\u01b0\u1edbc 3:</strong>\n                            Ch\u1ecdn v\u1eadt ph\u1ea9m ho\u1eb7c k\u00e8o \u0111\u1ed5i.\n                        </p>\n\n                        <p>\n                            <strong>B\u01b0\u1edbc 4:</strong>\n                            Ki\u1ec3m tra Phi\u1ebfu \u0111\u1ed5i qu\u00e0.\n                        </p>\n\n                        <p>\n                            <strong>B\u01b0\u1edbc 5:</strong>\n                            X\u00e1c nh\u1eadn giao d\u1ecbch.\n                        </p>\n\n                    </div>\n\n                </details>\n\n            </div>\n\n        </div>\n\n    </div>\n\n\n    <!--=====================================================\n         INSIGHT\n         KH\u00d4NG C\u00d2N MINH H\u1ed2NG / V\u1eacT PH\u1ea8M \u01afU TI\u00caN \u1ede \u0110\u00c2Y\n    ======================================================-->\n\n    <section id=\"studentInsightSection\">\n\n        <div class=\"insight-shell\">\n\n            <div class=\"insight-header\">\n\n                <div class=\"insight-kicker\">\n                    H\u1ed2 S\u01a0 PH\u00c2N T\u00cdCH C\u00c1 NH\u00c2N\n                </div>\n\n                <h2 class=\"insight-title\">\n                    S\u1ef1 ti\u1ebfn b\u1ed9 c\u1ee7a b\u1ea1n\n                </h2>\n\n                <p class=\"insight-desc\">\n                    H\u1ec7 th\u1ed1ng ph\u00e2n t\u00edch ti\u1ebfn \u0111\u1ed9 h\u1ecdc t\u1eadp,\n                    ch\u1ea5t l\u01b0\u1ee3ng c\u00e1c b\u00e0i g\u1ea7n \u0111\u00e2y v\u00e0 nh\u1eefng m\u1ee5c ti\u00eau\n                    \u0111ang \u1edf g\u1ea7n b\u1ea1n nh\u1ea5t.\n\n                </p>\n\n            </div>\n\n\n            <div class=\"insight-body\">\n\n                <div class=\"insight-loading\" id=\"studentInsightLoading\">\n                    \u0110ang ph\u00e2n t\u00edch qu\u00e1 tr\u00ecnh h\u1ecdc t\u1eadp...\n                </div>\n\n\n                <div class=\"insight-content\" id=\"studentInsightContent\">\n\n                    <!--SUMMARY-->\n\n                    <div class=\"insight-summary-grid\">\n\n                        <div class=\"insight-stat\">\n\n                            <span class=\"insight-stat-value\" id=\"insightLatest\">\n                                -\n                            </span>\n\n                            <span class=\"insight-stat-label\">\n                                B\u00e0i g\u1ea7n nh\u1ea5t\n                            </span>\n\n                        </div>\n\n\n                        <div class=\"insight-stat\">\n\n                            <span class=\"insight-stat-value\" id=\"insightHighest\">\n                                -\n                            </span>\n\n                            <span class=\"insight-stat-label\">\n                                \u0110i\u1ec3m cao nh\u1ea5t\n                            </span>\n\n                        </div>\n\n\n                        <div class=\"insight-stat\">\n\n                            <span class=\"insight-stat-value\" id=\"insightGraded\">\n                                0\n                            </span>\n\n                            <span class=\"insight-stat-label\">\n                                B\u00e0i \u0111\u00e3 ch\u1ea5m\n                            </span>\n\n                        </div>\n\n\n                        <div class=\"insight-stat\">\n\n                            <span class=\"insight-stat-value\" id=\"insightRank\">\n                                -\n                            </span>\n\n                            <span class=\"insight-stat-label\">\n                                Rank hi\u1ec7n t\u1ea1i\n                            </span>\n\n                        </div>\n\n                    </div>\n\n\n                    <!--RANK-->\n\n                    <div class=\"insight-rank-box\">\n\n                        <div>\n\n                            <div class=\"insight-rank-label\">\n                                Danh hi\u1ec7u Rank hi\u1ec7n t\u1ea1i\n                            </div>\n\n                            <div class=\"insight-rank-name\" id=\"studentCurrentRankTitle\">\n                                -\n                            </div>\n\n                            <div class=\"insight-rank-next\" id=\"studentRankNextText\"></div>\n\n                        </div>\n\n\n                        <div class=\"insight-rank-icon\" id=\"studentRankIcon\"></div>\n\n                    </div>\n\n\n                    <!--CHART-->\n\n                    <div class=\"insight-trend-row\">\n\n                        <div class=\"insight-card\">\n\n                            <div class=\"insight-card-title\">\n\n                                <span id=\"insightChartIcon\"></span>\n\n                                <span>\n                                    Bi\u1ec3u \u0111\u1ed3 ti\u1ebfn b\u1ed9\n                                </span>\n\n                            </div>\n\n\n                            <div class=\"insight-card-subtitle\">\n                                \u0110i\u1ec3m gi\u00e1o vi\u00ean ch\u1ea5m theo tr\u00ecnh t\u1ef1 th\u1eddi gian.\n                            </div>\n\n\n                            <div class=\"insight-chart-wrap\" id=\"studentChartWrap\">\n\n                                <svg id=\"studentProgressChart\" preserveaspectratio=\"none\" role=\"img\" viewbox=\"0 0 760 260\"></svg>\n\n\n                                <div class=\"insight-chart-empty\" id=\"studentChartEmpty\">\n                                    B\u1ea1n ch\u01b0a c\u00f3 \u0111\u1ee7 b\u00e0i \u0111\u01b0\u1ee3c ch\u1ea5m\n                                    \u0111\u1ec3 t\u1ea1o bi\u1ec3u \u0111\u1ed3 ti\u1ebfn b\u1ed9.\n                                </div>\n\n                            </div>\n\n                        </div>\n\n\n                        <div class=\"insight-card\">\n\n                            <div class=\"insight-trend-box insufficient\" id=\"studentTrendBox\">\n\n                                <div class=\"insight-trend-icon\" id=\"studentTrendIcon\"></div>\n\n                                <div class=\"insight-trend-name\" id=\"studentTrendName\">\n                                    Ch\u01b0a \u0111\u1ee7 d\u1eef li\u1ec7u\n                                </div>\n\n                                <div class=\"insight-trend-detail\" id=\"studentTrendDetail\">\n                                    H\u00e3y ho\u00e0n th\u00e0nh th\u00eam m\u1ed9t v\u00e0i b\u00e0i.\n                                </div>\n\n                            </div>\n\n                        </div>\n\n                    </div>\n\n\n                    <!--GOALS-->\n\n                    <div class=\"insight-section\">\n\n                        <div class=\"insight-section-head\">\n\n                            <div class=\"insight-section-title\">\n\n                                <span id=\"insightGoalIcon\"></span>\n\n                                <span>\n                                    M\u1ed1c m\u1ee5c ti\u00eau quan tr\u1ecdng\n                                </span>\n\n                            </div>\n\n                            <div class=\"insight-section-desc\">\n                                H\u1ec7 th\u1ed1ng \u01b0u ti\u00ean nh\u1eefng m\u1ee5c ti\u00eau\n                                \u0111ang \u1edf g\u1ea7n b\u1ea1n nh\u1ea5t.\n                            </div>\n\n                        </div>\n\n\n                        <div class=\"insight-goal-grid\" id=\"studentGoalGrid\"></div>\n\n                    </div>\n\n\n                    <div class=\"insight-note\" id=\"studentInsightNote\"></div>\n\n                </div>\n\n            </div>\n\n        </div>\n\n    </section>\n\n</div>\n\n\n<!--=========================================================\n     MODAL\n=========================================================-->\n\n<div class=\"rx-modal\" id=\"rxModal\">\n\n    <div class=\"rx-modal-box\">\n\n        <div class=\"rx-modal-title\">\n            PHI\u1ebeU \u0110\u1ed4I QU\u00c0\n        </div>\n\n        <div class=\"rx-ticket-notice\" id=\"rxTicketNotice\"></div>\n\n        <div class=\"rx-ticket\" id=\"rxTicket\"></div>\n\n        <button class=\"rx-form-confirm\" id=\"rxConfirmFormButton\" type=\"button\">\n            X\u00c1C NH\u1eacN \u0110\u1ed4I QU\u00c0\n        </button>\n\n        <div class=\"rx-form-help\" id=\"rxFormHelp\"></div>\n\n        <button class=\"rx-modal-close\" id=\"rxModalClose\" type=\"button\">\n            \u0110\u00f3ng\n        </button>\n\n    </div>\n\n</div>\n\n\n<iframe id=\"rxHiddenFormFrame\" name=\"rxHiddenFormFrame\" style=\"border: 0; display: none; height: 0; width: 0;\"></iframe>\n\n\n<!--=========================================================\n     SAFE ICONS\n=========================================================-->\n\n<script>\n(function(){\n\n\"use strict\";\n\n\nconst UI={\n\n    scroll:\n        String.fromCodePoint(0x1F4DC),\n\n    compass:\n        String.fromCodePoint(0x1F9ED),\n\n    down:\n        String.fromCodePoint(0x25BC),\n\n    chart:\n        String.fromCodePoint(0x1F4C8),\n\n    target:\n        String.fromCodePoint(0x1F3AF)\n\n};\n\n\nfunction setText(\n    id,\n    value\n){\n\n    const target=\n        document.getElementById(\n            id\n        );\n\n\n    if(target){\n\n        target.textContent=\n            value;\n    }\n\n}\n\n\nfunction start(){\n\n    setText(\n        \"marketIntroSafeIcon\",\n        UI.scroll\n    );\n\n\n    setText(\n        \"marketGuideSafeIcon\",\n        UI.compass\n    );\n\n\n    setText(\n        \"marketSafeArrow\",\n        UI.down\n    );\n\n\n    setText(\n        \"submissionSafeArrow\",\n        UI.down\n    );\n\n\n    setText(\n        \"insightChartIcon\",\n        UI.chart\n    );\n\n\n    setText(\n        \"insightGoalIcon\",\n        UI.target\n    );\n\n\n    document\n    .querySelectorAll(\n        \".safe-down-arrow\"\n    )\n    .forEach(\n        function(item){\n\n            item.textContent=\n                UI.down;\n\n        }\n    );\n\n}\n\n\nif(\n    document.readyState===\n    \"loading\"\n){\n\n    document.addEventListener(\n        \"DOMContentLoaded\",\n        start,\n        {\n            once:true\n        }\n    );\n\n}else{\n\n    start();\n}\n\n\n})();\n</script>\n\n\n<!--=========================================================\n     ADMIN PATCH\n=========================================================-->\n\n<script>\n(function(){\n\n\"use strict\";\n\n\nconst CONFIG={\n\n    code:\n        \"ADMIN\",\n\n    gradeUrl:\n        \"https://www.thudao.com/p/core-v31.html\",\n\n    giftUrl:\n        \"https://www.thudao.com/p/tess-linh-thu.html\",\n\n    graduationUrl:\n        \"https://www.thudao.com/p/gid.html\"\n\n};\n\n\nconst UI={\n\n    grade:\n        String.fromCodePoint(0x1F4DD),\n\n    gift:\n        String.fromCodePoint(0x1F381),\n\n    graduation:\n        String.fromCodePoint(0x1F393)\n\n};\n\n\nlet scheduled=\n    false;\n\n\nfunction elements(){\n\n    return{\n\n        input:\n            document.getElementById(\n                \"rxStudentCode\"\n            ),\n\n        streakIcon:\n            document.getElementById(\n                \"profileStreakIcon\"\n            ),\n\n        streakText:\n            document.getElementById(\n                \"profileStreakText\"\n            ),\n\n        highIcon:\n            document.getElementById(\n                \"profileHighIcon\"\n            ),\n\n        highText:\n            document.getElementById(\n                \"profileHighText\"\n            ),\n\n        titleIcon:\n            document.getElementById(\n                \"profileTitleIcon\"\n            ),\n\n        titleText:\n            document.getElementById(\n                \"profileTitleText\"\n            )\n\n    };\n\n}\n\n\nfunction isAdmin(){\n\n    const data=\n        elements();\n\n\n    return Boolean(\n\n        data.input\n\n        &&\n\n        String(\n            data.input.value ||\n            \"\"\n        )\n        .trim()\n        .toUpperCase()\n\n        ===\n\n        CONFIG.code\n\n    );\n\n}\n\n\nfunction resetBadge(\n    icon,\n    text\n){\n\n    if(!text){\n\n        return;\n    }\n\n\n    const badge=\n        text.closest(\n            \".student-profile-badge\"\n        );\n\n\n    if(badge){\n\n        badge.classList.remove(\n            \"admin-quick-action\"\n        );\n    }\n\n\n    if(icon){\n\n        icon.classList.remove(\n            \"admin-original-icon\"\n        );\n    }\n\n}\n\n\nfunction createButton(\n    icon,\n    text,\n    url,\n    iconString,\n    label,\n    cssClass\n){\n\n    if(!text){\n\n        return;\n    }\n\n\n    const badge=\n        text.closest(\n            \".student-profile-badge\"\n        );\n\n\n    if(!badge){\n\n        return;\n    }\n\n\n    badge.classList.add(\n        \"admin-quick-action\"\n    );\n\n\n    if(icon){\n\n        icon.classList.add(\n            \"admin-original-icon\"\n        );\n\n        icon.textContent=\n            \"\";\n    }\n\n\n    const current=\n        text.querySelector(\n            \".admin-profile-link\"\n        );\n\n\n    if(\n        current &&\n        current.getAttribute(\n            \"href\"\n        )===\n        url\n    ){\n\n        return;\n    }\n\n\n    text.textContent=\n        \"\";\n\n\n    const link=\n        document.createElement(\n            \"a\"\n        );\n\n\n    link.className=\n        \"admin-profile-link \"+\n        cssClass;\n\n\n    link.href=\n        url;\n\n\n    link.target=\n        \"_blank\";\n\n\n    link.rel=\n        \"noopener noreferrer\";\n\n\n    const iconNode=\n        document.createElement(\n            \"span\"\n        );\n\n\n    iconNode.textContent=\n        iconString;\n\n\n    const labelNode=\n        document.createElement(\n            \"span\"\n        );\n\n\n    labelNode.textContent=\n        label;\n\n\n    link.appendChild(\n        iconNode\n    );\n\n\n    link.appendChild(\n        labelNode\n    );\n\n\n    text.appendChild(\n        link\n    );\n\n}\n\n\nfunction patch(){\n\n    scheduled=\n        false;\n\n\n    const data=\n        elements();\n\n\n    if(\n        !data.streakText ||\n        !data.highText ||\n        !data.titleText\n    ){\n\n        return;\n    }\n\n\n    if(!isAdmin()){\n\n        resetBadge(\n            data.streakIcon,\n            data.streakText\n        );\n\n        resetBadge(\n            data.highIcon,\n            data.highText\n        );\n\n        resetBadge(\n            data.titleIcon,\n            data.titleText\n        );\n\n        return;\n    }\n\n\n    createButton(\n        data.streakIcon,\n        data.streakText,\n        CONFIG.gradeUrl,\n        UI.grade,\n        \"Ch\u1ea5m b\u00e0i\",\n        \"admin-grade-link\"\n    );\n\n\n    createButton(\n        data.highIcon,\n        data.highText,\n        CONFIG.giftUrl,\n        UI.gift,\n        \"T\u1eb7ng qu\u00e0 theo t\u1ed5\",\n        \"admin-gift-link\"\n    );\n\n\n    createButton(\n        data.titleIcon,\n        data.titleText,\n        CONFIG.graduationUrl,\n        UI.graduation,\n        \"Ch\u1ea5m b\u00e0i t\u1ed1t nghi\u1ec7p\",\n        \"admin-graduation-link\"\n    );\n\n}\n\n\nfunction schedule(){\n\n    if(scheduled){\n\n        return;\n    }\n\n\n    scheduled=\n        true;\n\n\n    requestAnimationFrame(\n        patch\n    );\n\n}\n\n\nfunction start(){\n\n    const profile=\n        document.getElementById(\n            \"studentProfileModule\"\n        );\n\n\n    if(profile){\n\n        new MutationObserver(\n            schedule\n        )\n        .observe(\n            profile,\n            {\n                subtree:true,\n                childList:true,\n                characterData:true\n            }\n        );\n\n    }\n\n\n    const input=\n        document.getElementById(\n            \"rxStudentCode\"\n        );\n\n\n    const button=\n        document.getElementById(\n            \"rxSearchButton\"\n        );\n\n\n    if(input){\n\n        input.addEventListener(\n            \"input\",\n            schedule\n        );\n    }\n\n\n    if(button){\n\n        button.addEventListener(\n            \"click\",\n            function(){\n\n                [\n                    0,\n                    200,\n                    600\n                ]\n                .forEach(\n                    function(delay){\n\n                        setTimeout(\n                            schedule,\n                            delay\n                        );\n\n                    }\n                );\n\n            }\n        );\n\n    }\n\n\n    schedule();\n\n}\n\n\nif(\n    document.readyState===\n    \"loading\"\n){\n\n    document.addEventListener(\n        \"DOMContentLoaded\",\n        start,\n        {\n            once:true\n        }\n    );\n\n}else{\n\n    start();\n}\n\n\n})();\n</script>\n\n\n<!--=========================================================\n     SESSION ADAPTER\n=========================================================-->\n\n<script>\n(function(){\n\n\"use strict\";\n\n\nif(\n    window.__OCD_PROFILE_SESSION_ADAPTER_V1__\n){\n\n    return;\n}\n\n\nwindow.__OCD_PROFILE_SESSION_ADAPTER_V1__=\n    true;\n\n\nconst CONFIG={\n\n    adminCode:\n        \"ADMIN\",\n\n    autoSearch:\n        true,\n\n    autoSearchDelay:\n        550\n\n};\n\n\nlet autoSearchUsed=\n    false;\n\n\nfunction normalize(value){\n\n    return String(\n        value ||\n        \"\"\n    )\n    .trim()\n    .toUpperCase()\n    .replace(\n        /\\s+/g,\n        \"\"\n    );\n\n}\n\n\nfunction sessionCode(){\n\n    try{\n\n        if(\n            window.OCDStudentSession &&\n            typeof window.OCDStudentSession.getCode===\n            \"function\"\n        ){\n\n            return normalize(\n                window.OCDStudentSession.getCode()\n            );\n\n        }\n\n    }catch(error){}\n\n\n    return \"\";\n\n}\n\n\nfunction fillFromSession(){\n\n    if(autoSearchUsed){\n\n        return;\n    }\n\n\n    const code=\n        sessionCode();\n\n\n    if(\n        !code ||\n        code===\n        CONFIG.adminCode\n    ){\n\n        return;\n    }\n\n\n    const input=\n        document.getElementById(\n            \"rxStudentCode\"\n        );\n\n\n    const button=\n        document.getElementById(\n            \"rxSearchButton\"\n        );\n\n\n    if(\n        !input ||\n        !button\n    ){\n\n        return;\n    }\n\n\n    /*\n       Kh\u00f4ng ghi \u0111\u00e8 n\u1ebfu ng\u01b0\u1eddi d\u00f9ng\n       \u0111\u00e3 t\u1ef1 nh\u1eadp m\u00e3 kh\u00e1c.\n    */\n\n    if(\n        normalize(\n            input.value\n        )\n        &&\n        normalize(\n            input.value\n        )!==\n        code\n    ){\n\n        return;\n    }\n\n\n    input.value=\n        code;\n\n\n    try{\n\n        input.dispatchEvent(\n            new Event(\n                \"input\",\n                {\n                    bubbles:true\n                }\n            )\n        );\n\n    }catch(error){}\n\n\n    if(\n        CONFIG.autoSearch\n    ){\n\n        autoSearchUsed=\n            true;\n\n\n        setTimeout(\n            function(){\n\n                /*\n                   Ki\u1ec3m tra l\u1ea1i \u0111\u1ec3 tr\u00e1nh tr\u01b0\u1eddng h\u1ee3p\n                   ng\u01b0\u1eddi d\u00f9ng \u0111\u00e3 s\u1eeda input.\n                */\n\n                if(\n                    normalize(\n                        input.value\n                    )===\n                    code\n                ){\n\n                    button.click();\n                }\n\n            },\n            CONFIG.autoSearchDelay\n        );\n\n    }\n\n}\n\n\nfunction start(){\n\n    setTimeout(\n        fillFromSession,\n        200\n    );\n\n}\n\n\nif(\n    document.readyState===\n    \"loading\"\n){\n\n    document.addEventListener(\n        \"DOMContentLoaded\",\n        start,\n        {\n            once:true\n        }\n    );\n\n}else{\n\n    start();\n}\n\n\n})();\n</script>\n\n\n<!--=========================================================\n     LEARNING INSIGHT v1.6\n=========================================================-->\n\n<script>\n(function(){\n\n\"use strict\";\n\n\nif(\n    window.OCDLearningInsightV16Loaded\n){\n\n    return;\n}\n\n\nwindow.OCDLearningInsightV16Loaded=\n    true;\n\n\n/* =========================================================\n   CONFIG\n========================================================= */\n\nconst CONFIG={\n\n    adminCode:\n        \"ADMIN\",\n\n    worksCsv:\n        \"https://docs.google.com/spreadsheets/d/e/2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/pub?gid=1023688821&single=true&output=csv\",\n\n    fallbackCsv:\n        \"https://docs.google.com/spreadsheets/d/1GJoTRsbq0kZfZrDdh0uCC667PwS3Bgkje2fHQnwnCKs/export?format=csv&gid=1837470623\",\n\n    deleteCsv:\n        \"https://docs.google.com/spreadsheets/d/1GJoTRsbq0kZfZrDdh0uCC667PwS3Bgkje2fHQnwnCKs/export?format=csv&gid=521976322\",\n\n    cacheVersion:\n        \"v16\",\n\n    cacheTTL:\n        5*60*1000,\n\n    graduationAverage:\n        7,\n\n    graduationSubmissions:\n        100,\n\n    scorePlanStart:\n        70,\n\n    trendWindow:\n        3,\n\n    recentWindow:\n        5,\n\n    mediumWindow:\n        10,\n\n    chartLimit:\n        18,\n\n    successWait:\n        10000\n\n};\n\n\n/* =========================================================\n   ICON\n========================================================= */\n\nconst UI={\n\n    rank:\n        String.fromCodePoint(0x1F3C6),\n\n    up:\n        String.fromCodePoint(0x2197),\n\n    down:\n        String.fromCodePoint(0x2198),\n\n    stable:\n        String.fromCodePoint(0x2192),\n\n    neutral:\n        String.fromCodePoint(0x2022),\n\n    tip:\n        String.fromCodePoint(0x1F4A1),\n\n    score:\n        String.fromCodePoint(0x1F4CA),\n\n    target:\n        String.fromCodePoint(0x1F3AF),\n\n    warning:\n        String.fromCodePoint(0x26A0),\n\n    check:\n        String.fromCodePoint(0x2705),\n\n    market:\n        String.fromCodePoint(0x1F3EA),\n\n    dice:\n        String.fromCodePoint(0x1F3B2),\n\n    gift:\n        String.fromCodePoint(0x1F381),\n\n    fire:\n        String.fromCodePoint(0x1F525)\n\n};\n\n\nconst CHAR={\n\n    openQuote:\n        String.fromCodePoint(0x201C),\n\n    closeQuote:\n        String.fromCodePoint(0x201D),\n\n    dash:\n        String.fromCodePoint(0x2014)\n\n};\n\n\n/* =========================================================\n   RANK\n========================================================= */\n\nconst RANK_LEVELS=[\n\n    {\n        min:0,\n        name:\"T\u00e2n th\u1ee7 nh\u1eadp m\u00f4n\"\n    },\n\n    {\n        min:100,\n        name:\"C\u1ea7m b\u00fat ch\u1eafc ch\u1eafn\"\n    },\n\n    {\n        min:300,\n        name:\"Bi\u1ebft c\u00e1ch l\u1ea5y m\u1ef1c\"\n    },\n\n    {\n        min:700,\n        name:\"L\u1ed9 phong \u0111\u1ec1u \u0111\u1eb7n\"\n    },\n\n    {\n        min:1500,\n        name:\"Trung phong s\u1eafc n\u00e9t\"\n    },\n\n    {\n        min:3000,\n        name:\"Nh\u00e3n l\u1ef1c n\u00e2ng cao\"\n    },\n\n    {\n        min:5000,\n        name:\"Ch\u01b0\u01a1ng ph\u00e1p \u1ed5n \u0111\u1ecbnh\"\n    },\n\n    {\n        min:8000,\n        name:\"Cao th\u1ee7\"\n    },\n\n    {\n        min:12000,\n        name:\"Tho\u00e1t t\u1ee5c t\u1ef1 nhi\u00ean\"\n    },\n\n    {\n        min:20000,\n        name:\"Th\u01b0 gia t\u1ed1 ch\u1ea5t\"\n    }\n\n];\n\n\nconst STREAK_RULES=[\n\n    {\n        target:5,\n        name:\"M\u1ea7m c\u00e2y ch\u0103m ch\u1ec9\"\n    },\n\n    {\n        target:7,\n        name:\"Phi\u1ebfu b\u00e9 ngoan\"\n    },\n\n    {\n        target:14,\n        name:\"C\u00e2y nh\u1ecf b\u1ec1n b\u1ec9\"\n    },\n\n    {\n        target:30,\n        name:\"Ng\u1ecdn l\u1eeda kh\u00f4ng t\u1eaft\"\n    }\n\n];\n\n\n/* =========================================================\n   STATE\n========================================================= */\n\nconst state={\n\n    RS:null,\n\n    works:null,\n\n    worksPromise:null,\n\n    deletedIds:\n        new Set(),\n\n    analysisCache:\n        new Map(),\n\n    giftCatalog:null,\n\n\n    currentAnalysis:null,\n\n\n    token:0,\n\n    scheduled:false,\n\n    marketObserver:null,\n\n    marketTimer:null\n\n};\n\n\n/* =========================================================\n   DOM\n========================================================= */\n\nfunction el(id){\n\n    return document.getElementById(\n        id\n    );\n\n}\n\n\n/* =========================================================\n   TEXT\n========================================================= */\n\nfunction decodeDisplayText(value){\n\n    return String(\n        value===undefined ||\n        value===null\n        ?\n        \"\"\n        :\n        value\n    )\n\n    .replace(\n        /&#x([0-9a-f]+);/gi,\n        function(\n            full,\n            hex\n        ){\n\n            const number=\n                parseInt(\n                    hex,\n                    16\n                );\n\n\n            return Number.isFinite(\n                number\n            )\n            ?\n            String.fromCodePoint(\n                number\n            )\n            :\n            full;\n\n        }\n    )\n\n    .replace(\n        /&#(\\d+);/g,\n        function(\n            full,\n            decimal\n        ){\n\n            const number=\n                parseInt(\n                    decimal,\n                    10\n                );\n\n\n            return Number.isFinite(\n                number\n            )\n            ?\n            String.fromCodePoint(\n                number\n            )\n            :\n            full;\n\n        }\n    )\n\n    .replace(\n        /&quot;/gi,\n        \"\\\"\"\n    )\n\n    .replace(\n        /&apos;/gi,\n        \"'\"\n    )\n\n    .replace(\n        /&#39;/gi,\n        \"'\"\n    )\n\n    .replace(\n        /&nbsp;/gi,\n        \" \"\n    )\n\n    .replace(\n        /&amp;/gi,\n        \"&\"\n    );\n\n}\n\n\nfunction clean(value){\n\n    return decodeDisplayText(\n        value\n    )\n    .trim();\n\n}\n\n\nfunction normalizeText(value){\n\n    return clean(\n        value\n    )\n    .toLowerCase()\n    .normalize(\"NFD\")\n    .replace(\n        /[\\u0300-\\u036f]/g,\n        \"\"\n    )\n    .replace(\n        /\u0111/g,\n        \"d\"\n    )\n    .replace(\n        /\\s+/g,\n        \" \"\n    );\n\n}\n\n\n/* =========================================================\n   CORE\n========================================================= */\n\nfunction getCore(){\n\n    const RS=\n        window.StudentRewardSystem;\n\n\n    if(\n        RS &&\n        typeof RS.normalizeCode===\n        \"function\"\n    ){\n\n        state.RS=\n            RS;\n\n\n        return RS;\n    }\n\n\n    return null;\n\n}\n\n\nfunction normalizeCode(value){\n\n    const RS=\n        getCore();\n\n\n    if(\n        RS &&\n        typeof RS.normalizeCode===\n        \"function\"\n    ){\n\n        return RS.normalizeCode(\n            value\n        );\n\n    }\n\n\n    return clean(\n        value\n    )\n    .toUpperCase()\n    .replace(\n        /\\s+/g,\n        \"\"\n    );\n\n}\n\n\n/* =========================================================\n   NUMBER\n========================================================= */\n\nfunction numberValue(value){\n\n    const number=\n        Number(\n            clean(\n                value\n            )\n            .replace(\n                /[^\\d,.\\-]/g,\n                \"\"\n            )\n            .replace(\n                \",\",\n                \".\"\n            )\n        );\n\n\n    return Number.isFinite(\n        number\n    )\n    ?\n    number\n    :\n    null;\n\n}\n\n\nfunction formatNumber(value){\n\n    const number=\n        Number(\n            value\n        );\n\n\n    if(\n        !Number.isFinite(\n            number\n        )\n    ){\n\n        return CHAR.dash;\n    }\n\n\n    return number.toLocaleString(\n        \"vi-VN\",\n        {\n            minimumFractionDigits:0,\n            maximumFractionDigits:2\n        }\n    );\n\n}\n\n\nfunction mean(values){\n\n    if(!values.length){\n\n        return null;\n    }\n\n\n    return(\n        values.reduce(\n            function(\n                total,\n                value\n            ){\n\n                return total+value;\n\n            },\n            0\n        )\n        /\n        values.length\n    );\n\n}\n\n\nfunction standardDeviation(values){\n\n    if(\n        values.length<2\n    ){\n\n        return null;\n    }\n\n\n    const avg=\n        mean(\n            values\n        );\n\n\n    return Math.sqrt(\n        mean(\n            values.map(\n                function(value){\n\n                    return Math.pow(\n                        value-avg,\n                        2\n                    );\n\n                }\n            )\n        )\n    );\n\n}\n\n\nfunction ratioAtLeast(\n    values,\n    threshold\n){\n\n    if(!values.length){\n\n        return 0;\n    }\n\n\n    return(\n        values.filter(\n            function(value){\n\n                return(\n                    value>=\n                    threshold\n                );\n\n            }\n        )\n        .length\n        /\n        values.length\n    );\n\n}\n\n\n/* =========================================================\n   IDLE\n========================================================= */\n\n\n\n/* =========================================================\n   CACHE\n========================================================= */\n\nfunction cacheKey(name){\n\n    return(\n        \"ocd-insight-\"+\n        CONFIG.cacheVersion+\n        \"-\"+\n        name\n    );\n\n}\n\n\nfunction readCache(name){\n\n    try{\n\n        const raw=\n            sessionStorage.getItem(\n                cacheKey(\n                    name\n                )\n            );\n\n\n        if(!raw){\n\n            return null;\n        }\n\n\n        const data=\n            JSON.parse(\n                raw\n            );\n\n\n        if(\n            !data ||\n            !data.time ||\n            Date.now()-\n            data.time>\n            CONFIG.cacheTTL\n        ){\n\n            sessionStorage.removeItem(\n                cacheKey(\n                    name\n                )\n            );\n\n\n            return null;\n        }\n\n\n        return data.value;\n\n    }catch(error){\n\n        return null;\n    }\n\n}\n\n\nfunction writeCache(\n    name,\n    value\n){\n\n    try{\n\n        sessionStorage.setItem(\n\n            cacheKey(\n                name\n            ),\n\n            JSON.stringify({\n\n                time:\n                    Date.now(),\n\n                value:\n                    value\n\n            })\n\n        );\n\n    }catch(error){}\n\n}\n\n\n/* =========================================================\n   CSV\n========================================================= */\n\nfunction parseCSV(text){\n\n    const rows=[];\n\n    let row=[];\n\n    let value=\"\";\n\n    let quoted=false;\n\n\n    text=\n        String(\n            text ||\n            \"\"\n        )\n        .replace(\n            /^\\uFEFF/,\n            \"\"\n        );\n\n\n    for(\n        let i=0;\n        i<text.length;\n        i++\n    ){\n\n        const char=\n            text[i];\n\n\n        if(char==='\"'){\n\n            if(\n                quoted &&\n                text[i+1]==='\"'\n            ){\n\n                value+='\"';\n\n                i++;\n\n            }else{\n\n                quoted=\n                    !quoted;\n            }\n\n\n            continue;\n        }\n\n\n        if(\n            char===\",\" &&\n            !quoted\n        ){\n\n            row.push(\n                value\n            );\n\n            value=\"\";\n\n            continue;\n        }\n\n\n        if(\n            (\n                char===\"\\n\" ||\n                char===\"\\r\"\n            )\n            &&\n            !quoted\n        ){\n\n            if(\n                char===\"\\r\" &&\n                text[i+1]===\"\\n\"\n            ){\n\n                i++;\n            }\n\n\n            row.push(\n                value\n            );\n\n\n            if(\n                row.some(\n                    function(cell){\n\n                        return clean(\n                            cell\n                        );\n\n                    }\n                )\n            ){\n\n                rows.push(\n                    row\n                );\n\n            }\n\n\n            row=[];\n\n            value=\"\";\n\n            continue;\n        }\n\n\n        value+=char;\n\n    }\n\n\n    if(\n        value ||\n        row.length\n    ){\n\n        row.push(\n            value\n        );\n\n\n        if(\n            row.some(\n                function(cell){\n\n                    return clean(\n                        cell\n                    );\n\n                }\n            )\n        ){\n\n            rows.push(\n                row\n            );\n\n        }\n\n    }\n\n\n    return rows;\n\n}\n\n\nfunction csvObjects(text){\n\n    const rows=\n        parseCSV(\n            text\n        );\n\n\n    if(\n        rows.length<2\n    ){\n\n        return [];\n    }\n\n\n    const headers=\n        rows[0]\n        .map(\n            normalizeText\n        );\n\n\n    return rows\n    .slice(1)\n    .filter(\n        function(row){\n\n            return row.some(\n                function(cell){\n\n                    return clean(\n                        cell\n                    );\n\n                }\n            );\n\n        }\n    )\n    .map(\n        function(row){\n\n            const object={};\n\n\n            headers.forEach(\n                function(\n                    header,\n                    index\n                ){\n\n                    if(header){\n\n                        object[header]=\n                            row[index] ||\n                            \"\";\n\n                    }\n\n                }\n            );\n\n\n            return object;\n\n        }\n    );\n\n}\n\n\nfunction column(\n    object,\n    aliases\n){\n\n    if(!object){\n\n        return \"\";\n    }\n\n\n    for(\n        const alias\n        of aliases\n    ){\n\n        const key=\n            normalizeText(\n                alias\n            );\n\n\n        if(\n            Object.prototype\n            .hasOwnProperty\n            .call(\n                object,\n                key\n            )\n        ){\n\n            return object[key];\n        }\n\n    }\n\n\n    return \"\";\n\n}\n\n\nasync function fetchText(\n    url,\n    cacheName\n){\n\n    const cached=\n        readCache(\n            cacheName\n        );\n\n\n    if(\n        typeof cached===\n        \"string\"\n        &&\n        cached.length\n    ){\n\n        return cached;\n    }\n\n\n    /* v1.7: \u0111\u1ecdc qua Apps Script (l\u1ecdc s\u1eb5n theo h\u1ecdc vi\u00ean, d\u1eef li\u1ec7u m\u1edbi ngay); l\u1ed7i th\u00ec t\u1ea3i CSV nh\u01b0 c\u0169 */\n    const RSX=window.StudentRewardSystem, byCode=String(url).split(\"#code=\")[1];\n    try{\n        let apiText=\"\";\n        if(RSX && byCode && typeof RSX.getStudentSheetCsv===\"function\"){\n            apiText=await RSX.getStudentSheetCsv(\"TacPhamWeb\",decodeURIComponent(byCode));\n        }else if(RSX && !byCode && typeof RSX.fetchCSV===\"function\"){\n            apiText=await RSX.fetchCSV(url);\n        }\n        if(apiText){ writeCache(cacheName,apiText); return apiText; }\n    }catch(error){}\n\n    const response=\n        await fetch(\n            url,\n            {\n                cache:\"no-cache\"\n            }\n        );\n\n\n    if(!response.ok){\n\n        throw new Error(\n            \"HTTP \"+\n            response.status\n        );\n    }\n\n\n    const text=\n        await response.text();\n\n\n    writeCache(\n        cacheName,\n        text\n    );\n\n\n    return text;\n\n}\n\n\n/* =========================================================\n   TIME\n========================================================= */\n\nfunction timeValue(value){\n\n    const text=\n        clean(\n            value\n        );\n\n\n    const match=\n        text.match(\n            /^(\\d{1,2})[\\/-](\\d{1,2})[\\/-](\\d{4})(?:[\\s,]+(\\d{1,2}):(\\d{2})(?::(\\d{2}))?)?/\n        );\n\n\n    if(match){\n\n        return new Date(\n\n            Number(match[3]),\n\n            Number(match[2])-1,\n\n            Number(match[1]),\n\n            Number(match[4] || 0),\n\n            Number(match[5] || 0),\n\n            Number(match[6] || 0)\n\n        ).getTime();\n\n    }\n\n\n    return(\n        Date.parse(\n            text\n        )\n        ||\n        0\n    );\n\n}\n\n\n/* =========================================================\n   SUBMISSION ID\n========================================================= */\n\nfunction driveId(value){\n\n    const text=\n        String(\n            value ||\n            \"\"\n        );\n\n\n    const patterns=[\n\n        /\\/file\\/d\\/([^/?&#]+)/i,\n\n        /\\/d\\/([^/?&#]+)/i,\n\n        /[?&]id=([^&#]+)/i\n\n    ];\n\n\n    for(\n        const pattern\n        of patterns\n    ){\n\n        const match=\n            text.match(\n                pattern\n            );\n\n\n        if(match){\n\n            return match[1];\n        }\n\n    }\n\n\n    return \"\";\n\n}\n\n\nfunction compactTime(value){\n\n    const match=\n        String(\n            value ||\n            \"\"\n        )\n        .match(\n            /^(\\d{1,2})[\\/-](\\d{1,2})[\\/-](\\d{4})[\\s,]+(\\d{1,2}):(\\d{2})(?::(\\d{2}))?/\n        );\n\n\n    if(!match){\n\n        return \"\";\n    }\n\n\n    function pad(value){\n\n        return String(\n            value\n        )\n        .padStart(\n            2,\n            \"0\"\n        );\n\n    }\n\n\n    return(\n        match[3]+\n        pad(match[2])+\n        pad(match[1])+\n        pad(match[4])+\n        pad(match[5])+\n        pad(match[6] || 0)\n    );\n\n}\n\n\nfunction submissionId(row){\n\n    const existing=\n        clean(\n            column(\n                row,\n                [\n                    \"M\u00e3 b\u00e0i n\u1ed9p\"\n                ]\n            )\n        );\n\n\n    if(existing){\n\n        return existing;\n    }\n\n\n    const timestamp=\n        column(\n            row,\n            [\n                \"D\u1ea5u th\u1eddi gian\"\n            ]\n        );\n\n\n    const code=\n        clean(\n            column(\n                row,\n                [\n                    \"M\u00e3 h\u1ecdc vi\u00ean\"\n                ]\n            )\n        );\n\n\n    const file=\n        column(\n            row,\n            [\n                \"T\u1ea3i b\u00e0i t\u1eadp l\u00ean\"\n            ]\n        );\n\n\n    return(\n        compactTime(\n            timestamp\n        )\n        +\n        \"|\"+\n        code+\n        \"|\"+\n        (\n            driveId(\n                file\n            )\n            ||\n            clean(\n                file\n            )\n        )\n    );\n\n}\n\n\n/* =========================================================\n   DELETE LOG\n========================================================= */\n\nfunction buildDeletedIds(rows){\n\n    const map=\n        new Map();\n\n\n    rows.forEach(\n        function(row){\n\n            const id=\n                clean(\n                    column(\n                        row,\n                        [\n                            \"M\u00e3 b\u00e0i n\u1ed9p\"\n                        ]\n                    )\n                );\n\n\n            if(!id){\n\n                return;\n            }\n\n\n            const action=\n                normalizeText(\n                    column(\n                        row,\n                        [\n                            \"H\u00e0nh \u0111\u1ed9ng\"\n                        ]\n                    )\n                );\n\n\n            if(\n                action.includes(\n                    \"khoi phuc\"\n                )\n                ||\n                action===\n                \"restore\"\n            ){\n\n                map.set(\n                    id,\n                    false\n                );\n\n\n                return;\n            }\n\n\n            if(\n                !action\n                ||\n                action.includes(\n                    \"xoa\"\n                )\n                ||\n                action===\n                \"delete\"\n            ){\n\n                map.set(\n                    id,\n                    true\n                );\n\n            }\n\n        }\n    );\n\n\n    state.deletedIds=\n        new Set();\n\n\n    map.forEach(\n        function(\n            deleted,\n            id\n        ){\n\n            if(deleted){\n\n                state.deletedIds.add(\n                    id\n                );\n            }\n\n        }\n    );\n\n}\n\n\n/* =========================================================\n   WORK\n========================================================= */\n\n/* v1.7.1: gi\u1eef th\u00eam m\u00f4 t\u1ea3 b\u00e0i \u0111\u1ec3 t\u00ednh Ng\u0169 gi\u00e1c ch\u1ec9 s\u1ed1 (D\u1ee5ng b\u00fat / Th\u1ee9c th\u1ebf / Kho\u1ea3 th\u00fac) */\nfunction workDescription(row){\n    if(!row) return \"\";\n    const key=Object.keys(row).find(function(k){ return k.indexOf(\"mo ta\")===0; });\n    return key?clean(row[key]):\"\";\n}\nfunction prepareWork(row){\n    const work=prepareWorkBase(row);\n    work.description=workDescription(row);\n    return work;\n}\nfunction prepareWorkBase(row){\n\n    const timestamp=\n        clean(\n            column(\n                row,\n                [\n                    \"D\u1ea5u th\u1eddi gian\"\n                ]\n            )\n        );\n\n\n    return{\n\n        id:\n            submissionId(\n                row\n            ),\n\n        code:\n            normalizeCode(\n                column(\n                    row,\n                    [\n                        \"M\u00e3 h\u1ecdc vi\u00ean\"\n                    ]\n                )\n            ),\n\n        timestamp:\n            timestamp,\n\n        time:\n            timeValue(\n                timestamp\n            ),\n\n        score:\n            clean(\n                column(\n                    row,\n                    [\n                        \"\u0110i\u1ec3m s\u1ed1\",\n                        \"\u0110i\u1ec3m\",\n                        \"\u0110i\u1ec3m gi\u00e1o vi\u00ean\"\n                    ]\n                )\n            )\n\n    };\n\n}\n\n\nasync function loadWorks(code){\n    /* v1.7: d\u1eef li\u1ec7u theo t\u1eebng h\u1ecdc vi\u00ean */\n    if(state.worksCode!==String(code||\"\")){ state.works=null; state.worksPromise=null; state.worksCode=String(code||\"\"); }\n\n    if(state.works){\n\n        return state.works;\n    }\n\n\n    if(state.worksPromise){\n\n        return state.worksPromise;\n    }\n\n\n    state.worksPromise=\n        (async function(){\n\n            let text=\"\";\n\n\n            try{\n\n                text=\n                    await fetchText(\n                        CONFIG.worksCsv+\"#code=\"+encodeURIComponent(String(code||\"\")),\n                        \"works:\"+String(code||\"\")\n                    );\n\n            }catch(error){}\n\n\n            if(!text){\n\n                text=\n                    await fetchText(\n                        CONFIG.fallbackCsv,\n                        \"fallback\"\n                    );\n\n            }\n\n\n            try{\n\n                const deleteText=\n                    await fetchText(\n                        CONFIG.deleteCsv,\n                        \"delete\"\n                    );\n\n\n                buildDeletedIds(\n                    csvObjects(\n                        deleteText\n                    )\n                );\n\n            }catch(error){\n\n                state.deletedIds=\n                    new Set();\n\n            }\n\n\n            if(state.worksCode!==String(code||\"\")) return [];\n            state.works=\n                csvObjects(\n                    text\n                )\n                .filter(\n                    function(row){\n\n                        return(\n                            !state.deletedIds.has(\n                                submissionId(\n                                    row\n                                )\n                            )\n                        );\n\n                    }\n                )\n                .map(\n                    prepareWork\n                )\n                .filter(\n                    function(item){\n\n                        return(\n                            item.code &&\n                            item.time>0\n                        );\n\n                    }\n                );\n\n\n            return state.works;\n\n        })()\n        .finally(\n            function(){\n\n                state.worksPromise=\n                    null;\n\n            }\n        );\n\n\n    return state.worksPromise;\n\n}\n\n\n/* =========================================================\n   SCORE\n========================================================= */\n\nfunction parseScore(value){\n\n    const RS=\n        getCore();\n\n\n    if(\n        RS &&\n        typeof RS.parseScore===\n        \"function\"\n    ){\n\n        const result=\n            RS.parseScore(\n                value\n            );\n\n\n        return Number.isFinite(\n            result\n        )\n        ?\n        result\n        :\n        null;\n\n    }\n\n\n    return numberValue(\n        value\n    );\n\n}\n\n\nfunction studentWorks(\n    code,\n    all\n){\n\n    const normalized=\n        normalizeCode(\n            code\n        );\n\n\n    return all\n    .filter(\n        function(item){\n\n            return(\n                item.code===\n                normalized\n            );\n\n        }\n    )\n    .sort(\n        function(a,b){\n\n            return a.time-b.time;\n\n        }\n    );\n\n}\n\n\nfunction gradedWorks(works){\n\n    return works\n    .map(\n        function(item){\n\n            return Object.assign(\n                {},\n                item,\n                {\n                    parsedScore:\n                        parseScore(\n                            item.score\n                        )\n                }\n            );\n\n        }\n    )\n    .filter(\n        function(item){\n\n            return(\n                item.parsedScore!==\n                null\n            );\n\n        }\n    );\n\n}\n\n\n/* =========================================================\n   TREND\n========================================================= */\n\nfunction calculateTrend(scores){\n\n    if(\n        scores.length<4\n    ){\n\n        return{\n\n            type:\n                \"insufficient\",\n\n            change:\n                null\n\n        };\n\n    }\n\n\n    const size=\n        Math.min(\n            CONFIG.trendWindow,\n            Math.floor(\n                scores.length/\n                2\n            )\n        );\n\n\n    const recent=\n        mean(\n            scores.slice(\n                -size\n            )\n        );\n\n\n    const previous=\n        mean(\n            scores.slice(\n                -size*2,\n                -size\n            )\n        );\n\n\n    const change=\n        recent-\n        previous;\n\n\n    return{\n\n        type:\n            change>=.35\n            ?\n            \"up\"\n            :\n            (\n                change<=-.35\n                ?\n                \"down\"\n                :\n                \"stable\"\n            ),\n\n        change:\n            change\n\n    };\n\n}\n\n\n/* =========================================================\n   STREAK\n========================================================= */\n\nfunction dayNumber(ms){\n\n    const date=\n        new Date(\n            ms\n        );\n\n\n    return Math.floor(\n        Date.UTC(\n\n            date.getFullYear(),\n\n            date.getMonth(),\n\n            date.getDate()\n\n        )\n        /\n        86400000\n    );\n\n}\n\n\nfunction longestStreak(works){\n\n    const days=\n        Array.from(\n            new Set(\n                works.map(\n                    function(item){\n\n                        return dayNumber(\n                            item.time\n                        );\n\n                    }\n                )\n            )\n        )\n        .sort(\n            function(a,b){\n\n                return a-b;\n\n            }\n        );\n\n\n    let best=0;\n\n    let current=0;\n\n    let previous=null;\n\n\n    days.forEach(\n        function(day){\n\n            if(\n                previous!==\n                null\n                &&\n                day-previous===\n                1\n            ){\n\n                current++;\n\n            }else{\n\n                current=1;\n\n            }\n\n\n            best=\n                Math.max(\n                    best,\n                    current\n                );\n\n\n            previous=\n                day;\n\n        }\n    );\n\n\n    return best;\n\n}\n\n\n/* =========================================================\n   RANK\n========================================================= */\n\nfunction rankLevel(rank){\n\n    for(\n        let i=\n            RANK_LEVELS.length-1;\n        i>=0;\n        i--\n    ){\n\n        if(\n            rank>=\n            RANK_LEVELS[i].min\n        ){\n\n            return RANK_LEVELS[i];\n\n        }\n\n    }\n\n\n    return RANK_LEVELS[0];\n\n}\n\n\nfunction nextRankLevel(rank){\n\n    return(\n        RANK_LEVELS.find(\n            function(level){\n\n                return(\n                    level.min>\n                    rank\n                );\n\n            }\n        )\n        ||\n        null\n    );\n\n}\n\n\n/* =========================================================\n   ASSETS\n========================================================= */\n\nfunction readHongNgoc(){\n\n    let balance=0;\n\n\n    document\n    .querySelectorAll(\n        \"#profileGemGrid .profile-gem-card\"\n    )\n    .forEach(\n        function(card){\n\n            const nameNode=\n                card.querySelector(\n                    \".profile-gem-name\"\n                );\n\n\n            const valueNode=\n                card.querySelector(\n                    \".profile-gem-value\"\n                );\n\n\n            const name=\n                normalizeText(\n                    nameNode\n                    ?\n                    nameNode.textContent\n                    :\n                    \"\"\n                );\n\n\n            if(\n                !name.includes(\n                    \"hong ngoc\"\n                )\n                &&\n                !name.includes(\n                    \"hong thach\"\n                )\n            ){\n\n                return;\n            }\n\n\n            const number=\n                numberValue(\n                    valueNode\n                    ?\n                    valueNode.textContent\n                    :\n                    \"\"\n                );\n\n\n            if(\n                number!==\n                null\n            ){\n\n                balance=\n                    number;\n\n            }\n\n        }\n    );\n\n\n    return balance;\n\n}\n\n\nfunction readOwnedItems(){\n\n    const list=[];\n\n\n    document\n    .querySelectorAll(\n        \"#profileItemGrid .profile-item-name\"\n    )\n    .forEach(\n        function(item){\n\n            const value=\n                clean(\n                    item.textContent\n                );\n\n\n            if(value){\n\n                list.push(\n                    value\n                );\n\n            }\n\n        }\n    );\n\n\n    return list;\n\n}\n\n\n/* =========================================================\n   RECOVERY PLAN\n========================================================= */\n\nfunction calculateRecoveryPlan(analysis){\n\n    if(\n        analysis.average===\n        null\n        ||\n        analysis.average>=7\n        ||\n        analysis.totalSubmissions<\n        CONFIG.scorePlanStart\n        ||\n        analysis.totalSubmissions>=100\n    ){\n\n        return null;\n    }\n\n\n    const remaining=\n        100-\n        analysis.totalSubmissions;\n\n\n    const requiredTotal=\n        700;\n\n\n    const requiredAverage=\n        (\n            requiredTotal-\n            analysis.scoreTotal\n        )\n        /\n        remaining;\n\n\n    const normal=\n        analysis.recent10Average===\n        null\n        ?\n        analysis.average\n        :\n        analysis.recent10Average;\n\n\n    let highScore=\n        Math.max(\n            8,\n            analysis.highest ||\n            8\n        );\n\n\n    highScore=\n        Math.min(\n            10,\n            highScore\n        );\n\n\n    if(\n        requiredAverage<=\n        normal\n    ){\n\n        return{\n\n            possible:true,\n\n            remaining:\n                remaining,\n\n            requiredAverage:\n                requiredAverage,\n\n            normalScore:\n                normal,\n\n            highScore:\n                highScore,\n\n            highNeeded:\n                0\n\n        };\n\n    }\n\n\n    const bestPossible=\n        analysis.scoreTotal+\n        remaining*\n        highScore;\n\n\n    if(\n        bestPossible<\n        requiredTotal\n    ){\n\n        return{\n\n            possible:false,\n\n            remaining:\n                remaining,\n\n            requiredAverage:\n                requiredAverage,\n\n            normalScore:\n                normal,\n\n            highScore:\n                highScore,\n\n            bestPossibleAverage:\n                bestPossible/\n                100\n\n        };\n\n    }\n\n\n    const denominator=\n        highScore-\n        normal;\n\n\n    if(\n        denominator<=0\n    ){\n\n        return{\n\n            possible:false,\n\n            remaining:\n                remaining,\n\n            requiredAverage:\n                requiredAverage,\n\n            normalScore:\n                normal,\n\n            highScore:\n                highScore\n\n        };\n\n    }\n\n\n    const needed=\n        Math.ceil(\n            (\n                requiredTotal-\n                analysis.scoreTotal-\n                remaining*\n                normal\n            )\n            /\n            denominator\n        );\n\n\n    return{\n\n        possible:true,\n\n        remaining:\n            remaining,\n\n        requiredAverage:\n            requiredAverage,\n\n        normalScore:\n            normal,\n\n        highScore:\n            highScore,\n\n        highNeeded:\n            Math.max(\n                0,\n                Math.min(\n                    remaining,\n                    needed\n                )\n            )\n\n    };\n\n}\n\n\n/* =========================================================\n   ANALYSIS\n========================================================= */\n\nfunction buildAnalysis(\n    code,\n    works\n){\n\n    const graded=\n        gradedWorks(\n            works\n        );\n\n\n    const scores=\n        graded.map(\n            function(item){\n\n                return item.parsedScore;\n\n            }\n        );\n\n\n    const scoreTotal=\n        scores.reduce(\n            function(\n                total,\n                value\n            ){\n\n                return total+value;\n\n            },\n            0\n        );\n\n\n    const recent5=\n        scores.slice(\n            -5\n        );\n\n\n    const recent10=\n        scores.slice(\n            -10\n        );\n\n\n    const rank=\n        works.length+\n        scoreTotal;\n\n\n    const analysis={\n\n        code:\n            code,\n\n        works:\n            works,\n\n        graded:\n            graded,\n\n        scores:\n            scores,\n\n        totalSubmissions:\n            works.length,\n\n        gradedSubmissions:\n            graded.length,\n\n        scoreTotal:\n            scoreTotal,\n\n        rank:\n            rank,\n\n        average:\n            scores.length\n            ?\n            mean(\n                scores\n            )\n            :\n            null,\n\n        latest:\n            scores.length\n            ?\n            scores[\n                scores.length-1\n            ]\n            :\n            null,\n\n        highest:\n            scores.length\n            ?\n            Math.max(\n                ...scores\n            )\n            :\n            null,\n\n        recent5Average:\n            recent5.length\n            ?\n            mean(\n                recent5\n            )\n            :\n            null,\n\n        recent10Average:\n            recent10.length\n            ?\n            mean(\n                recent10\n            )\n            :\n            null,\n\n        recent5Deviation:\n            standardDeviation(\n                recent5\n            ),\n\n        ratio7:\n            ratioAtLeast(\n                recent10,\n                7\n            ),\n\n        ratio8:\n            ratioAtLeast(\n                recent10,\n                8\n            ),\n\n        trend:\n            calculateTrend(\n                scores\n            ),\n\n        longestStreak:\n            longestStreak(\n                works\n            ),\n\n        currentRankLevel:\n            rankLevel(\n                rank\n            ),\n\n        nextRankLevel:\n            nextRankLevel(\n                rank\n            ),\n\n        hongNgoc:\n            readHongNgoc(),\n\n        ownedItems:\n            readOwnedItems(),\n\n        scoreRecoveryPlan:\n            null\n\n    };\n\n\n    analysis.scoreRecoveryPlan=\n        calculateRecoveryPlan(\n            analysis\n        );\n\n\n    return analysis;\n\n}\n\n\n/* =========================================================\n   SUMMARY\n========================================================= */\n\nfunction renderSummary(analysis){\n\n    el(\"insightLatest\")\n    .textContent=\n        analysis.latest===\n        null\n        ?\n        CHAR.dash\n        :\n        formatNumber(\n            analysis.latest\n        );\n\n\n    el(\"insightHighest\")\n    .textContent=\n        analysis.highest===\n        null\n        ?\n        CHAR.dash\n        :\n        formatNumber(\n            analysis.highest\n        );\n\n\n    el(\"insightGraded\")\n    .textContent=\n        String(\n            analysis.gradedSubmissions\n        );\n\n\n    el(\"insightRank\")\n    .textContent=\n        formatNumber(\n            analysis.rank\n        );\n\n}\n\n\n/* =========================================================\n   RANK DISPLAY\n========================================================= */\n\nfunction renderRank(analysis){\n\n    el(\"studentRankIcon\")\n    .textContent=\n        UI.rank;\n\n\n    el(\"studentCurrentRankTitle\")\n    .textContent=\n        clean(\n            analysis.currentRankLevel.name\n        );\n\n\n    const target=\n        el(\n            \"studentRankNextText\"\n        );\n\n\n    if(\n        !analysis.nextRankLevel\n    ){\n\n        target.textContent=\n            \"B\u1ea1n \u0111\u00e3 \u0111\u1ea1t c\u1ea5p Rank cao nh\u1ea5t hi\u1ec7n t\u1ea1i.\";\n\n\n        return;\n    }\n\n\n    const remaining=\n        analysis.nextRankLevel.min-\n        analysis.rank;\n\n\n    let text=\n        \"C\u00f2n \"+\n        formatNumber(\n            remaining\n        )+\n        \" Rank \u0111\u1ec3 m\u1edf kh\u00f3a \"+\n        CHAR.openQuote+\n        clean(\n            analysis.nextRankLevel.name\n        )+\n        CHAR.closeQuote+\n        \".\";\n\n\n    if(\n        analysis.recent5Average!==null\n        &&\n        analysis.recent5Average>0\n    ){\n\n        const estimated=\n            Math.ceil(\n                remaining/\n                (\n                    1+\n                    analysis.recent5Average\n                )\n            );\n\n\n        text+=\n            \" Theo phong \u0111\u1ed9 g\u1ea7n \u0111\u00e2y, kho\u1ea3ng \"+\n            estimated+\n            \" b\u00e0i n\u1eefa.\";\n\n    }\n\n\n    target.textContent=\n        text;\n\n}\n\n\n/* =========================================================\n   TREND\n========================================================= */\n\n\n\nfunction renderTrend(analysis){\n\n    const box=\n        el(\n            \"studentTrendBox\"\n        );\n\n\n    const icon=\n        el(\n            \"studentTrendIcon\"\n        );\n\n\n    const name=\n        el(\n            \"studentTrendName\"\n        );\n\n\n    const detail=\n        el(\n            \"studentTrendDetail\"\n        );\n\n\n    box.className=\n        \"insight-trend-box \"+\n        analysis.trend.type;\n\n\n    if(\n        analysis.trend.type===\n        \"up\"\n    ){\n\n        icon.textContent=\n            UI.up;\n\n\n        name.textContent=\n            \"\u0110ang ti\u1ebfn b\u1ed9\";\n\n\n        detail.textContent=\n            \"Nh\u00f3m b\u00e0i g\u1ea7n \u0111\u00e2y t\u0103ng kho\u1ea3ng \"+\n            formatNumber(\n                Math.abs(\n                    analysis.trend.change\n                )\n            )+\n            \" \u0111i\u1ec3m.\";\n\n\n        return;\n    }\n\n\n    if(\n        analysis.trend.type===\n        \"down\"\n    ){\n\n        icon.textContent=\n            UI.down;\n\n\n        name.textContent=\n            \"\u0110ang gi\u1ea3m\";\n\n\n        detail.textContent=\n            \"Nh\u00f3m b\u00e0i g\u1ea7n \u0111\u00e2y gi\u1ea3m kho\u1ea3ng \"+\n            formatNumber(\n                Math.abs(\n                    analysis.trend.change\n                )\n            )+\n            \" \u0111i\u1ec3m.\";\n\n\n        return;\n    }\n\n\n    if(\n        analysis.trend.type===\n        \"stable\"\n    ){\n\n        icon.textContent=\n            UI.stable;\n\n\n        name.textContent=\n            \"\u1ed4n \u0111\u1ecbnh\";\n\n\n        detail.textContent=\n            \"C\u00e1c nh\u00f3m b\u00e0i g\u1ea7n \u0111\u00e2y ch\u01b0a c\u00f3 bi\u1ebfn \u0111\u1ed9ng l\u1edbn.\";\n\n\n        return;\n    }\n\n\n    icon.textContent=\n        UI.neutral;\n\n\n    name.textContent=\n        \"Ch\u01b0a \u0111\u1ee7 d\u1eef li\u1ec7u\";\n\n\n    detail.textContent=\n        \"H\u00e3y ho\u00e0n th\u00e0nh th\u00eam m\u1ed9t v\u00e0i b\u00e0i \u0111\u01b0\u1ee3c ch\u1ea5m.\";\n\n}\n\n\n/* =========================================================\n   GOALS\n========================================================= */\n\nfunction createGoal(\n    name,\n    current,\n    target,\n    detail,\n    priority\n){\n\n    return{\n\n        name:\n            name,\n\n        current:\n            current,\n\n        target:\n            target,\n\n        detail:\n            detail,\n\n        priority:\n            priority,\n\n        distance:\n            Math.max(\n                0,\n                (\n                    target-\n                    current\n                )\n                /\n                Math.max(\n                    target,\n                    1\n                )\n            ),\n\n        percent:\n            Math.min(\n                100,\n                Math.max(\n                    0,\n                    current/\n                    Math.max(\n                        target,\n                        1\n                    )*\n                    100\n                )\n            )\n\n    };\n\n}\n\n\nfunction buildGoals(analysis){\n\n    const list=[];\n\n\n    if(\n        analysis.nextRankLevel\n    ){\n\n        list.push(\n            createGoal(\n\n                analysis.nextRankLevel.name,\n\n                analysis.rank,\n\n                analysis.nextRankLevel.min,\n\n                \"C\u00f2n \"+\n                formatNumber(\n                    analysis.nextRankLevel.min-\n                    analysis.rank\n                )+\n                \" Rank.\",\n\n                15\n\n            )\n        );\n\n    }\n\n\n    if(\n        analysis.totalSubmissions<\n        100\n    ){\n\n        list.push(\n            createGoal(\n\n                \"100 b\u00e0i t\u1eadp h\u1ee3p l\u1ec7\",\n\n                analysis.totalSubmissions,\n\n                100,\n\n                \"C\u00f2n \"+\n                (\n                    100-\n                    analysis.totalSubmissions\n                )+\n                \" b\u00e0i.\",\n\n                10\n\n            )\n        );\n\n    }\n\n\n    const streak=\n        STREAK_RULES.find(\n            function(rule){\n\n                return(\n                    rule.target>\n                    analysis.longestStreak\n                );\n\n            }\n        );\n\n\n    if(streak){\n\n        list.push(\n            createGoal(\n\n                streak.name,\n\n                analysis.longestStreak,\n\n                streak.target,\n\n                \"C\u00f2n \"+\n                (\n                    streak.target-\n                    analysis.longestStreak\n                )+\n                \" ng\u00e0y li\u00ean ti\u1ebfp.\",\n\n                7\n\n            )\n        );\n\n    }\n\n\n    return list\n    .sort(\n        function(a,b){\n\n            return(\n                (\n                    a.distance-\n                    a.priority*.015\n                )\n                -\n                (\n                    b.distance-\n                    b.priority*.015\n                )\n            );\n\n        }\n    )\n    .slice(\n        0,\n        3\n    );\n\n}\n\n\nfunction renderGoals(analysis){\n\n    const root=\n        el(\n            \"studentGoalGrid\"\n        );\n\n\n    root.textContent=\n        \"\";\n\n\n    const goals=\n        buildGoals(\n            analysis\n        );\n\n\n    const labels=[\n\n        \"G\u1ea7n nh\u1ea5t\",\n\n        \"Ti\u1ebfp theo\",\n\n        \"M\u1ee5c ti\u00eau d\u00e0i h\u1ea1n\"\n\n    ];\n\n\n    goals.forEach(\n        function(\n            item,\n            index\n        ){\n\n            const card=\n                document.createElement(\n                    \"div\"\n                );\n\n\n            card.className=\n                \"insight-goal\";\n\n\n            const badge=\n                document.createElement(\n                    \"div\"\n                );\n\n\n            badge.className=\n                \"insight-goal-badge\";\n\n\n            badge.textContent=\n                labels[index];\n\n\n            const name=\n                document.createElement(\n                    \"div\"\n                );\n\n\n            name.className=\n                \"insight-goal-name\";\n\n\n            name.textContent=\n                item.name;\n\n\n            const detail=\n                document.createElement(\n                    \"div\"\n                );\n\n\n            detail.className=\n                \"insight-goal-detail\";\n\n\n            detail.textContent=\n                item.detail;\n\n\n            const progress=\n                document.createElement(\n                    \"div\"\n                );\n\n\n            progress.className=\n                \"insight-progress\";\n\n\n            const bar=\n                document.createElement(\n                    \"div\"\n                );\n\n\n            bar.className=\n                \"insight-progress-bar\";\n\n\n            bar.style.width=\n                item.percent+\n                \"%\";\n\n\n            progress.appendChild(\n                bar\n            );\n\n\n            const caption=\n                document.createElement(\n                    \"div\"\n                );\n\n\n            caption.className=\n                \"insight-progress-caption\";\n\n\n            caption.textContent=\n                formatNumber(\n                    item.current\n                )+\n                \" / \"+\n                formatNumber(\n                    item.target\n                );\n\n\n            card.appendChild(\n                badge\n            );\n\n\n            card.appendChild(\n                name\n            );\n\n\n            card.appendChild(\n                detail\n            );\n\n\n            card.appendChild(\n                progress\n            );\n\n\n            card.appendChild(\n                caption\n            );\n\n\n            root.appendChild(\n                card\n            );\n\n        }\n    );\n\n}\n\n\n/* =========================================================\n   SVG CHART\n========================================================= */\n\nconst SVG_NS=\n    \"http://www.w3.org/2000/svg\";\n\n\nfunction svgNode(\n    tag,\n    attributes\n){\n\n    const item=\n        document.createElementNS(\n            SVG_NS,\n            tag\n        );\n\n\n    Object.keys(\n        attributes ||\n        {}\n    )\n    .forEach(\n        function(key){\n\n            item.setAttribute(\n                key,\n                attributes[key]\n            );\n\n        }\n    );\n\n\n    return item;\n\n}\n\n\nfunction svgText(\n    x,\n    y,\n    text,\n    options\n){\n\n    options=\n        options ||\n        {};\n\n\n    const item=\n        svgNode(\n            \"text\",\n            {\n                x:\n                    x,\n\n                y:\n                    y,\n\n                fill:\n                    options.fill ||\n                    \"#78716c\",\n\n                \"font-size\":\n                    options.size ||\n                    \"10\",\n\n                \"font-family\":\n                    \"Arial, Helvetica, sans-serif\",\n\n                \"font-weight\":\n                    options.weight ||\n                    \"400\",\n\n                \"text-anchor\":\n                    options.anchor ||\n                    \"middle\"\n            }\n        );\n\n\n    item.textContent=\n        text;\n\n\n    return item;\n\n}\n\n\nfunction drawChart(analysis){\n\n    const svg=\n        el(\n            \"studentProgressChart\"\n        );\n\n\n    const empty=\n        el(\n            \"studentChartEmpty\"\n        );\n\n\n    const wrap=\n        el(\n            \"studentChartWrap\"\n        );\n\n\n    svg.textContent=\n        \"\";\n\n\n    const items=\n        analysis.graded\n        .slice(\n            -CONFIG.chartLimit\n        );\n\n\n    if(\n        items.length<2\n    ){\n\n        wrap.classList.add(\n            \"is-empty\"\n        );\n\n\n        empty.classList.add(\n            \"visible\"\n        );\n\n\n        return;\n    }\n\n\n    wrap.classList.remove(\n        \"is-empty\"\n    );\n\n\n    empty.classList.remove(\n        \"visible\"\n    );\n\n\n    const WIDTH=760;\n\n    const HEIGHT=260;\n\n    const LEFT=44;\n\n    const RIGHT=20;\n\n    const TOP=18;\n\n    const BOTTOM=38;\n\n\n    const chartWidth=\n        WIDTH-\n        LEFT-\n        RIGHT;\n\n\n    const chartHeight=\n        HEIGHT-\n        TOP-\n        BOTTOM;\n\n\n    for(\n        let score=0;\n        score<=10;\n        score+=2\n    ){\n\n        const y=\n            TOP+\n            chartHeight-\n            score/10*\n            chartHeight;\n\n\n        svg.appendChild(\n            svgNode(\n                \"line\",\n                {\n                    x1:\n                        LEFT,\n\n                    y1:\n                        y,\n\n                    x2:\n                        LEFT+\n                        chartWidth,\n\n                    y2:\n                        y,\n\n                    stroke:\n                        \"#e7e2dc\",\n\n                    \"stroke-width\":\n                        \"1\"\n                }\n            )\n        );\n\n\n        svg.appendChild(\n            svgText(\n                LEFT-9,\n                y+3,\n                String(score),\n                {\n                    anchor:\n                        \"end\"\n                }\n            )\n        );\n\n    }\n\n\n    const points=\n        items.map(\n            function(\n                item,\n                index\n            ){\n\n                return{\n\n                    x:\n                        LEFT+\n                        index/\n                        (\n                            items.length-1\n                        )*\n                        chartWidth,\n\n                    y:\n                        TOP+\n                        chartHeight-\n                        Math.max(\n                            0,\n                            Math.min(\n                                10,\n                                item.parsedScore\n                            )\n                        )\n                        /\n                        10*\n                        chartHeight,\n\n                    score:\n                        item.parsedScore\n\n                };\n\n            }\n        );\n\n\n    const path=\n        points.map(\n            function(\n                point,\n                index\n            ){\n\n                return(\n                    (\n                        index\n                        ?\n                        \"L \"\n                        :\n                        \"M \"\n                    )\n                    +\n                    point.x+\n                    \" \"+\n                    point.y\n                );\n\n            }\n        )\n        .join(\n            \" \"\n        );\n\n\n    svg.appendChild(\n        svgNode(\n            \"path\",\n            {\n                d:\n                    path,\n\n                fill:\n                    \"none\",\n\n                stroke:\n                    \"#b45309\",\n\n                \"stroke-width\":\n                    \"3\",\n\n                \"stroke-linecap\":\n                    \"round\",\n\n                \"stroke-linejoin\":\n                    \"round\"\n            }\n        )\n    );\n\n\n    points.forEach(\n        function(point){\n\n            svg.appendChild(\n                svgNode(\n                    \"circle\",\n                    {\n                        cx:\n                            point.x,\n\n                        cy:\n                            point.y,\n\n                        r:\n                            4,\n\n                        fill:\n                            \"#fff\",\n\n                        stroke:\n                            \"#b45309\",\n\n                        \"stroke-width\":\n                            \"2.5\"\n                    }\n                )\n            );\n\n        }\n    );\n\n}\n\n\n/* =========================================================\n   SESSION CONFIRM\n========================================================= */\n\nfunction confirmStudentSession(code){\n\n    if(\n        !code ||\n        code===\n        CONFIG.adminCode\n    ){\n\n        return;\n    }\n\n\n    try{\n\n        if(\n            window.OCDStudentSession &&\n            typeof window.OCDStudentSession.confirmStudent===\n            \"function\"\n        ){\n\n            window.OCDStudentSession.confirmStudent(\n                code,\n                \"student-profile-page\"\n            );\n\n        }\n\n    }catch(error){}\n\n}\n\n\n/* =========================================================\n   NOTE\n========================================================= */\n\nfunction renderNote(analysis){\n\n    el(\"studentInsightNote\")\n    .textContent=\n        \"Ph\u00e2n t\u00edch \u0111\u01b0\u1ee3c t\u1ea1o t\u1eeb \"+\n        analysis.totalSubmissions+\n        \" b\u00e0i h\u1ee3p l\u1ec7 v\u00e0 \"+\n        analysis.gradedSubmissions+\n        \" b\u00e0i \u0111\u00e3 c\u00f3 \u0111i\u1ec3m.\";\n\n}\n\n\n/* =========================================================\n   RENDER\n========================================================= */\n\nfunction renderBase(analysis){\n    try{ if(window.OCDPentagon) window.OCDPentagon.render(analysis); }catch(e){}\n\n    state.currentAnalysis=\n        analysis;\n\n\n\n\n    renderSummary(\n        analysis\n    );\n\n\n    renderRank(\n        analysis\n    );\n\n\n    renderTrend(\n        analysis\n    );\n\n\n    renderGoals(\n        analysis\n    );\n\n\n    renderNote(\n        analysis\n    );\n\n\n    el(\"studentInsightLoading\")\n    .classList.remove(\n        \"visible\"\n    );\n\n\n    el(\"studentInsightContent\")\n    .classList.add(\n        \"visible\"\n    );\n\n\n    requestAnimationFrame(\n        function(){\n\n            drawChart(\n                analysis\n            );\n\n        }\n    );\n\n\n\n}\n\n\n/* =========================================================\n   UI\n========================================================= */\n\nfunction hideInsight(){\n    try{ if(window.OCDPentagon) window.OCDPentagon.hide(); }catch(e){}\n\n    const section=\n        el(\n            \"studentInsightSection\"\n        );\n\n\n    const loading=\n        el(\n            \"studentInsightLoading\"\n        );\n\n\n    const content=\n        el(\n            \"studentInsightContent\"\n        );\n\n\n    if(section){\n\n        section.classList.remove(\n            \"visible\"\n        );\n    }\n\n\n    if(loading){\n\n        loading.classList.remove(\n            \"visible\"\n        );\n    }\n\n\n    if(content){\n\n        content.classList.remove(\n            \"visible\"\n        );\n    }\n\n}\n\n\nfunction showLoading(){\n    try{ if(window.OCDPentagon) window.OCDPentagon.loading(el(\"rxStudentCode\")&&el(\"rxStudentCode\").value); }catch(e){}\n\n    el(\"studentInsightSection\")\n    .classList.add(\n        \"visible\"\n    );\n\n\n    el(\"studentInsightLoading\")\n    .classList.add(\n        \"visible\"\n    );\n\n\n    el(\"studentInsightContent\")\n    .classList.remove(\n        \"visible\"\n    );\n\n}\n\n\n/* =========================================================\n   SUCCESS\n========================================================= */\n\nfunction profileReady(){ if(document.getElementById(\"studentProfileModule\") && document.getElementById(\"studentProfileModule\").classList.contains(\"card-only\")) return false; /* v4.10: danh thi\u1ebfp kh\u00f4ng ph\u00e2n t\u00edch */\n\n    const profile=\n        el(\n            \"studentProfileModule\"\n        );\n\n\n    const name=\n        el(\n            \"studentProfileName\"\n        );\n\n\n    if(\n        !profile ||\n        !name ||\n        !clean(\n            name.textContent\n        )\n    ){\n\n        return false;\n    }\n\n\n    return(\n        window\n        .getComputedStyle(\n            profile\n        )\n        .display!==\n        \"none\"\n    );\n\n}\n\n\nfunction searchSuccess(){\n\n    const message=\n        el(\n            \"rxMessage\"\n        );\n\n\n    if(!message){\n\n        return false;\n    }\n\n\n    return(\n\n        message.classList.contains(\n            \"success\"\n        )\n\n        ||\n\n        normalizeText(\n            message.textContent\n        )\n        .includes(\n            \"thanh cong\"\n        )\n\n    );\n\n}\n\n\nasync function waitSuccess(\n    code,\n    token\n){\n\n    const start=\n        Date.now();\n\n\n    while(\n        Date.now()-\n        start<\n        CONFIG.successWait\n    ){\n\n        if(\n            token!==\n            state.token\n        ){\n\n            return false;\n        }\n\n\n        const input=\n            el(\n                \"rxStudentCode\"\n            );\n\n\n        if(\n            !input ||\n            normalizeCode(\n                input.value\n            )!==\n            code\n        ){\n\n            return false;\n        }\n\n\n        if(\n            profileReady()\n            &&\n            searchSuccess()\n        ){\n\n            return true;\n        }\n\n\n        await new Promise(\n            function(resolve){\n\n                setTimeout(\n                    resolve,\n                    120\n                );\n\n            }\n        );\n\n    }\n\n\n    return false;\n\n}\n\n\n/* =========================================================\n   ANALYSE\n========================================================= */\n\nasync function analyse(){\n\n    const input=\n        el(\n            \"rxStudentCode\"\n        );\n\n\n    if(!input){\n\n        return;\n    }\n\n\n    const code=\n        normalizeCode(\n            input.value\n        );\n\n\n    if(\n        !code\n        ||\n        code===\n        CONFIG.adminCode\n    ){\n\n        hideInsight();\n\n\n        return;\n    }\n\n\n    const token=\n        ++state.token;\n\n\n    state.currentAnalysis=\n        null;\n\n\n\n\n    hideInsight();\n\n\n    const success=\n        await waitSuccess(\n            code,\n            token\n        );\n\n\n    if(\n        !success\n        ||\n        token!==\n        state.token\n    ){\n\n        return;\n    }\n\n\n    /*\n       \u0110\u00e2y l\u00e0 \u0111i\u1ec3m duy nh\u1ea5t x\u00e1c minh\n       phi\u00ean \u0111\u0103ng nh\u1eadp h\u1ecdc vi\u00ean d\u00f9ng chung (OCDStudentSession).\n    */\n\n    confirmStudentSession(\n        code\n    );\n\n\n    showLoading();\n\n\n    await new Promise(\n        function(resolve){\n\n            setTimeout(\n                resolve,\n                150\n            );\n\n        }\n    );\n\n\n    try{\n\n        if(\n            state.analysisCache.has(\n                code\n            )\n        ){\n\n            const cached=\n                state.analysisCache.get(\n                    code\n                );\n\n\n            cached.hongNgoc=\n                readHongNgoc();\n\n\n            cached.ownedItems=\n                readOwnedItems();\n\n\n            cached.scoreRecoveryPlan=\n                calculateRecoveryPlan(\n                    cached\n                );\n\n\n            renderBase(\n                cached\n            );\n\n\n            return;\n        }\n\n\n        const allWorks=\n            await loadWorks(code);\n\n\n        if(\n            token!==\n            state.token\n        ){\n\n            return;\n        }\n\n\n        const works=\n            studentWorks(\n                code,\n                allWorks\n            );\n\n\n        await new Promise(\n            function(resolve){\n\n                setTimeout(\n                    resolve,\n                    80\n                );\n\n            }\n        );\n\n\n        const analysis=\n            buildAnalysis(\n                code,\n                works\n            );\n\n\n        state.analysisCache.set(\n            code,\n            analysis\n        );\n\n\n        renderBase(\n            analysis\n        );\n\n\n    }catch(error){\n\n        console.error(\n            \"[Learning Insight v1.6]\",\n            error\n        );\n\n\n        el(\"studentInsightLoading\")\n        .textContent=\n            \"Kh\u00f4ng t\u1ea3i \u0111\u01b0\u1ee3c d\u1eef li\u1ec7u ph\u00e2n t\u00edch. H\u1ed3 s\u01a1 v\u00e0 Ch\u1ee3 phi\u00ean v\u1eabn ho\u1ea1t \u0111\u1ed9ng b\u00ecnh th\u01b0\u1eddng.\";\n        try{ if(window.OCDPentagon) window.OCDPentagon.fail(); }catch(e){}\n\n    }\n\n}\n\n\n/* =========================================================\n   SCHEDULE\n========================================================= */\n\nfunction scheduleAnalyse(){\n\n    if(state.scheduled){\n\n        return;\n    }\n\n\n    state.scheduled=\n        true;\n\n\n    requestAnimationFrame(\n        function(){\n\n            state.scheduled=\n                false;\n\n\n            analyse();\n\n        }\n    );\n\n}\n\n\n/* =========================================================\n   EVENTS\n========================================================= */\n\nfunction bindEvents(){\n\n    const input=\n        el(\n            \"rxStudentCode\"\n        );\n\n\n    const search=\n        el(\n            \"rxSearchButton\"\n        );\n\n\n    if(input){\n\n        input.addEventListener(\n            \"input\",\n            function(){\n\n                ++state.token;\n\n\n                state.currentAnalysis=\n                    null;\n\n\n\n\n                hideInsight();\n\n            }\n        );\n\n\n        input.addEventListener(\n            \"keydown\",\n            function(event){\n\n                if(\n                    event.key===\n                    \"Enter\"\n                ){\n\n                    setTimeout(\n                        scheduleAnalyse,\n                        0\n                    );\n\n                }\n\n            }\n        );\n\n    }\n\n\n    if(search){\n\n        search.addEventListener(\n            \"click\",\n            function(){\n\n                setTimeout(\n                    scheduleAnalyse,\n                    0\n                );\n\n            }\n        );\n\n    }\n\n\n\n}\n\n\n/* =========================================================\n   START\n========================================================= */\n\nfunction start(){\n\n    getCore();\n\n\n    bindEvents();\n\n\n\n\n    hideInsight();\n\n}\n\n\nif(\n    document.readyState===\n    \"loading\"\n){\n\n    document.addEventListener(\n        \"DOMContentLoaded\",\n        start,\n        {\n            once:true\n        }\n    );\n\n}else{\n\n    start();\n}\n\n\n})();\n</script>\n\n\n</div>\n\n\n\n");})();
